const rawEntries = [
  ["91", "histoire", "Dourdan et son château", "Le château de Dourdan, construit au début du XIIIe siècle, montre une forteresse capétienne très lisible avec donjon, courtines et fossés. Il rappelle que l'Essonne depasse largement l'image d'une peripherie parisienne. Le département possède aussi des places médiévales liées au pouvoir royal.", 2, "commune", "neutre", "Château de Dourdan", "dourdan-chateau"],
  ["91", "histoire", "Étampes ville royale", "Étampes fut une ville importante du domaine royal, avec églises, marchés et fortifications. Sa tour de Guinette domine encore la ville et rappelle ce passé stratégique. Dans l'Essonne, l'histoire médiévale se lit souvent dans ces villes de vallée, longtemps plus centrales qu'elles ne paraissent aujourd'hui.", 2, "commune", "pédagogique", "Ville d'Étampes", "etampes-royale"],
  ["91", "histoire", "Corbeil et les Grands Moulins", "Corbeil a longtemps vécu avec les moulins, les grains et la Seine. Les Grands Moulins rappellent une histoire industrielle et alimentaire liée à l'approvisionnement de Paris. En Essonne, la proximité de la capitale a souvent transformé les rivières en machines économiques très concrètes.", 3, "peu commune", "pédagogique", "Archives municipales de Corbeil-Essonnes", "corbeil-moulins"],
  ["91", "histoire", "Milly et Jean Cocteau", "Jean Cocteau repose à Milly-la-Forêt, dans la chapelle Saint-Blaise-des-Simples qu'il a décorée. Le lieu relie poésie, dessin, plantes médicinales et mémoire intime. Dans l'Essonne, un village du Gâtinais devient un point d'entrée très personnel dans l'art du XXe siècle. Le fait ajoute une memoire locale precise.", 2, "commune", "poétique", "Maison Jean Cocteau", "cocteau-milly"],
  ["91", "histoire", "Montlhéry et sa tour", "La tour de Montlhéry domine le sud francilien depuis une butte stratégique. Elle rappelle un château médiéval lié aux routes entre Paris, Orléans et le Hurepoix. Dans l'Essonne, quelques ruines suffisent à montrer l'ancienne importance des passages terrestres. Cette nuance donne plus d'epaisseur au lieu.", 3, "peu commune", "neutre", "Commune de Montlhéry", "montlhery-tour"],
  ["91", "histoire", "Juvisy et Flammarion", "Camille Flammarion installe son observatoire à Juvisy-sur-Orge au XIXe siècle. Le lieu devient un repère pour la vulgarisation astronomique et l'observation du ciel. En Essonne, la science precede largement Saclay : elle possède aussi une histoire populaire tournée vers les étoiles.", 3, "peu commune", "surprenant", "Société astronomique de France", "flammarion-juvisy"],
  ["91", "histoire", "Évry ville nouvelle", "Évry devient l'un des grands projets de ville nouvelle de la région parisienne. Urbanisme, préfecture, université et cathédrale moderne y dessinent une centralité récente. Dans l'Essonne, une partie de l'identité départementale s'est construite par la planification plutôt que par l'accumulation médiévale.", 2, "commune", "pédagogique", "Archives départementales de l'Essonne", "evry-ville-nouvelle"],
  ["91", "histoire", "Saclay scientifique", "Le plateau de Saclay est devenu un grand pôle scientifique et universitaire, avec écoles, laboratoires et centres de recherche. Cette concentration transforme l'image de l'Essonne. Le département y passe du paysage agricole francilien à une carte de l'innovation, des campus et des grands équipements.", 1, "commune", "neutre", "Université Paris-Saclay", "saclay-science"],
  ["91", "histoire", "Mennecy et la porcelaine", "Mennecy a connu au XVIIIe siècle une production de porcelaine tendre associée à Villeroy. Cette histoire artisanale surprend dans un département souvent lu par ses routes et ses zones d'activité. L'Essonne conserve ainsi une mémoire de luxe discret et d'ateliers spécialisés.", 4, "rare", "surprenant", "Archives départementales de l'Essonne", "mennecy-porcelaine"],
  ["91", "histoire", "L'autodrome de Linas-Montlhéry", "L'autodrome de Linas-Montlhéry, inauguré dans l'entre-deux-guerres, a marqué l'histoire automobile française par son anneau de vitesse. Records, essais et compétitions y ont laissé une mémoire mécanique forte. En Essonne, le patrimoine technique peut prendre la forme d'une piste en béton.", 2, "commune", "surprenant", "UTAC Linas-Montlhéry", "autodrome-montlhery"],
  ["91", "géographie", "La vallée de l'Essonne", "La rivière Essonne donne son nom au département et traverse des paysages de marais, moulins et villages. Sa vallée apporte une respiration verte au sud francilien. Ici, la géographie départementale ne se limite pas aux villes nouvelles : elle suit aussi une rivière discrète.", 1, "commune", "neutre", "Syndicat de la rivière Essonne", "vallee-essonne"],
  ["91", "géographie", "Le plateau de Saclay", "Le plateau de Saclay mêle terres agricoles, campus scientifiques et zones humides. Cette cohabitation donne un paysage de tensions très francilien, entre recherche, urbanisation et protection des sols. Dans l'Essonne, un plateau peut devenir un laboratoire territorial autant qu'un site scientifique.", 1, "commune", "pédagogique", "Établissement public d'aménagement Paris-Saclay", "plateau-saclay"],
  ["91", "géographie", "Le Gâtinais essonnien", "Le sud de l'Essonne appartient au Gâtinais français, avec villages de pierre, cultures, bois et vallées sèches. Cette partie du département tranche avec l'image dense de la banlieue parisienne. L'Essonne y devient plus rurale, plus lente, presque déjà tournée vers la Beauce.", 2, "commune", "neutre", "Parc naturel régional du Gâtinais français", "gatinais-essonne"],
  ["91", "géographie", "Les vallées de l'Orge", "L'Orge traverse plusieurs communes de l'Essonne avant de rejoindre la Seine. Ses berges, bassins et anciens moulins racontent un département construit autour de petites vallées urbanisées. La rivière sert de lien entre pavillons, parcs, voies ferrées et mémoire artisanale. Le detail fait mieux sentir le terrain.", 2, "commune", "pédagogique", "Syndicat de l'Orge", "vallee-orge"],
  ["91", "géographie", "La Seine en Essonne", "La Seine borde et traverse une partie du nord-est de l'Essonne, autour de Corbeil-Essonnes ou Athis-Mons. Le fleuve a porté moulins, industries, ports et quartiers populaires. Le département possède ainsi une façade fluviale souvent moins visible que ses plateaux et vallées intérieures.", 2, "commune", "neutre", "Seine Grands Lacs", "seine-essonne"],
  ["91", "gastronomie", "Le cresson de Méréville", "Méréville est associé au cresson, cultivé dans des eaux fraîches et courantes. Cette production donne au sud de l'Essonne une spécialité végétale très précise. Le département y montre une gastronomie de sources, de bassins et de maraîchage, loin des clichés de banlieue.", 2, "commune", "neutre", "Site remarquable du goût Méréville", "cresson-mereville"],
  ["91", "gastronomie", "La menthe de Milly", "Milly-la-Forêt est connue pour ses plantes aromatiques et médicinales, notamment la menthe poivrée. Cette tradition donne une saveur très reconnaissable au Gâtinais essonnien. Dans l'Essonne, la gastronomie peut passer par une plante fraîche, presque pharmaceutique, cultivée dans un paysage rural.", 2, "commune", "surprenant", "Conservatoire national des plantes de Milly-la-Forêt", "menthe-milly"],
  ["91", "gastronomie", "Le pâté d'Étampes", "Le pâté d'Étampes est une spécialité ancienne, souvent associée au gibier et aux tables de fête. Son nom rappelle l'importance historique de la ville sur les routes du sud de Paris. En Essonne, la gourmandise locale garde parfois un accent très ancien et bourgeois.", 3, "peu commune", "neutre", "Ville d'Étampes", "pate-etampes"],
  ["91", "gastronomie", "Le miel du Gâtinais", "Le Gâtinais essonnien produit des miels liés aux cultures, aux bois et aux fleurs de plateau. Cette gourmandise simple raconte une Essonne rurale, très différente des grands axes franciliens. Le département y révèle un paysage de ruchers, de champs et de petites productions locales.", 3, "peu commune", "neutre", "Parc naturel régional du Gâtinais français", "miel-gatinais"],
  ["91", "gastronomie", "Les moulins de Corbeil", "Les Grands Moulins de Corbeil rappellent que la farine fut un enjeu majeur de l'alimentation parisienne. Ce n'est pas un plat, mais une base de cuisine essentielle. En Essonne, la gastronomie passe aussi par les infrastructures qui nourrissaient la capitale.", 3, "peu commune", "pédagogique", "Archives municipales de Corbeil-Essonnes", "farine-corbeil"],
  ["91", "culture", "Caillebotte à Yerres", "La propriété Caillebotte à Yerres permet de comprendre une partie de l'univers du peintre impressionniste. Jardins, rivière et maison composent un décor devenu sujet de peinture. En Essonne, l'impressionnisme ne se limite pas aux bords de Seine célèbres : il passe aussi par l'Yerres.", 1, "commune", "neutre", "Maison Caillebotte", "caillebotte-yerres"],
  ["91", "culture", "Le Cyclop de Milly", "Le Cyclop de Jean Tinguely, à Milly-la-Forêt, est une sculpture monumentale collective cachée dans les bois. Son œil de miroir, ses mécaniques et son échelle surprennent fortement. Dans l'Essonne, l'art contemporain peut surgir comme une machine étrange au cœur du Gâtinais.", 2, "commune", "surprenant", "Le Cyclop", "cyclop-milly"],
  ["91", "culture", "Chamarande art contemporain", "Le domaine de Chamarande associe château, parc historique et programmation d'art contemporain. Ce mélange évite de figer le lieu en simple décor patrimonial. En Essonne, la culture joue souvent sur ces contrastes entre héritage aristocratique, promenade publique et créations actuelles.", 2, "commune", "neutre", "Domaine départemental de Chamarande", "chamarande"],
  ["91", "culture", "L'Opéra de Massy", "L'Opéra de Massy donne à l'Essonne un équipement lyrique rare en grande couronne parisienne. Sa présence surprend dans une ville souvent associée aux transports et aux zones d'activité. Le département y montre une ambition culturelle qui ne dépend pas du centre de Paris.", 2, "commune", "surprenant", "Opéra de Massy", "opera-massy"],
  ["91", "culture", "La science de Saclay", "Les campus de Saclay produisent aussi une culture scientifique faite de conférences, musées, laboratoires ouverts et rencontres publiques. Le savoir devient un élément du territoire. En Essonne, la culture passe aussi par les sciences : elle se lit dans les sciences et les campus.", 2, "commune", "pédagogique", "Université Paris-Saclay", "culture-saclay"],
  ["91", "insolite", "Une cathédrale très moderne", "La cathédrale de la Résurrection à Évry surprend par sa forme cylindrique, sa brique et sa création récente. Elle tranche avec l'image traditionnelle des cathédrales gothiques. En Essonne, un monument religieux majeur peut appartenir pleinement à l'urbanisme de la fin du XXe siècle.", 1, "commune", "surprenant", "Diocèse d'Évry", "cathedrale-evry"],
  ["91", "insolite", "Le ciel de Juvisy", "L'observatoire de Camille Flammarion à Juvisy rappelle qu'un lieu de banlieue peut devenir un poste d'observation du cosmos. Le contraste entre ville dense et regard astronomique est fort. Dans l'Essonne, l'insolite tient parfois à lever les yeux depuis un paysage très quotidien.", 3, "peu commune", "poétique", "Société astronomique de France", "observatoire-juvisy"],
  ["91", "insolite", "Un monstre dans les bois", "Le Cyclop de Milly-la-Forêt ressemble à une créature mécanique installée dans la forêt. On ne tombe pas sur lui comme sur une statue classique. Dans l'Essonne, l'art contemporain prend ici une forme ludique, monumentale et presque secrète. La scene devient plus facile a situer.", 2, "commune", "surprenant", "Le Cyclop", "cyclop-insolite"],
  ["91", "insolite", "Un anneau de vitesse", "L'autodrome de Linas-Montlhéry conserve un anneau de vitesse spectaculaire, incliné et très reconnaissable. Ce paysage de béton évoque les records automobiles plus que les routes ordinaires. En Essonne, la passion mécanique a laissé une architecture sportive presque irréelle. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "UTAC Linas-Montlhéry", "anneau-montlhery"],
  ["91", "insolite", "La banlieue et les champs", "L'Essonne surprend par ses contrastes rapides entre grands ensembles, campus, vallées boisées et villages agricoles. Peu de kilomètres suffisent à changer d'ambiance. Dans le jeu, ce département rappelle que l'Ile-de-France associe densite urbaine et des marges rurales très nettes. Le repere reste simple et concret.", 1, "commune", "pédagogique", "Conseil départemental de l'Essonne", "contrastes-essonne"],

  ["92", "histoire", "La Malmaison de Joséphine", "Le château de Malmaison, à Rueil, fut la demeure de Joséphine et de Napoléon Bonaparte. Le lieu garde une mémoire impériale plus intime que les grands palais parisiens. Dans les Hauts-de-Seine, l'histoire nationale se découvre aussi dans une maison de campagne devenue musée.", 1, "commune", "neutre", "Musée national des châteaux de Malmaison et Bois-Préau", "malmaison"],
  ["92", "histoire", "Sèvres et la porcelaine", "La manufacture de Sèvres a donné aux Hauts-de-Seine une place majeure dans les arts décoratifs français. Porcelaine, couleurs et savoir-faire y rencontrent commandes royales puis nationales. Le département possède ainsi une histoire de luxe public, très différente de son image de bureaux.", 1, "commune", "pédagogique", "Sèvres - Manufacture et Musée nationaux", "sevres-porcelaine"],
  ["92", "histoire", "Le Mont-Valérien", "Le Mont-Valérien fut un lieu d'exécution pendant l'Occupation, puis un haut lieu de mémoire nationale. Sa position dominante au-dessus de Paris renforce sa charge symbolique. Dans les Hauts-de-Seine, un relief discret porte une histoire grave de résistance, de répression et de commémoration.", 1, "commune", "neutre", "Mémorial de la France combattante", "mont-valerien"],
  ["92", "histoire", "Nanterre et Mai 68", "L'université de Nanterre est l'un des lieux associés au déclenchement du mouvement de Mai 68. Campus, contestations étudiantes et transformation sociale y ont laissé une mémoire forte. Dans les Hauts-de-Seine, l'histoire contemporaine ne se résume pas aux tours de La Défense.", 2, "commune", "pédagogique", "Université Paris Nanterre", "nanterre-68"],
  ["92", "histoire", "L'île Seguin industrielle", "L'île Seguin, à Boulogne-Billancourt, fut longtemps marquée par l'usine Renault. Cette histoire ouvrière a structuré la ville et l'imaginaire industriel français. Dans les Hauts-de-Seine, une île de la Seine peut raconter le travail à la chaîne autant que la reconversion culturelle.", 1, "commune", "neutre", "Archives municipales de Boulogne-Billancourt", "ile-seguin-renault"],
  ["92", "histoire", "Saint-Cloud disparu", "Le château de Saint-Cloud, résidence princière puis impériale, a disparu après la guerre de 1870. Son parc conserve pourtant la trace d'un pouvoir absent. Dans les Hauts-de-Seine, l'histoire se lit parfois dans un vide monumental, là où un palais n'existe plus.", 3, "peu commune", "surprenant", "Domaine national de Saint-Cloud", "saint-cloud-chateau"],
  ["92", "histoire", "Meudon et l'observatoire", "Meudon accueille un observatoire important, installé dans un site lié à l'ancien château. Astronomie, instruments et recherche y donnent une profondeur scientifique au département. Les Hauts-de-Seine regardent aussi le ciel depuis leurs coteaux. Le recit reste court, mais plus incarne.", 2, "commune", "pédagogique", "Observatoire de Paris - site de Meudon", "meudon-observatoire"],
  ["92", "histoire", "La Défense grand projet", "La Défense naît comme un grand quartier d'affaires planifié à l'ouest de Paris. Dalles, tours et infrastructures y ont construit un paysage totalement différent des faubourgs anciens. Dans les Hauts-de-Seine, l'urbanisme du XXe siècle devient un marqueur historique majeur. Cette mention ajoute une accroche memorable.", 1, "commune", "neutre", "Paris La Défense", "la-defense"],
  ["92", "histoire", "Sceaux et Colbert", "Le domaine de Sceaux garde la mémoire de Colbert et de grandes transformations classiques. Parc, château reconstruit et collections racontent une aristocratie proche de Paris. Dans les Hauts-de-Seine, le patrimoine de cour subsiste au milieu d'un département très urbanisé. Le point complete la scene sans l'alourdir.", 2, "commune", "neutre", "Domaine départemental de Sceaux", "sceaux-colbert"],
  ["92", "histoire", "Clichy industrielle", "Clichy et les communes voisines ont connu une forte histoire industrielle, entre imprimeries, cosmétiques, mécanique et ateliers. Cette mémoire explique une partie de la densité urbaine actuelle. Dans les Hauts-de-Seine, l'activité productive a précédé les sièges sociaux et les immeubles de bureaux.", 3, "peu commune", "pédagogique", "Archives départementales des Hauts-de-Seine", "clichy-industrielle"],
  ["92", "géographie", "Les boucles de la Seine", "Les Hauts-de-Seine suivent plusieurs courbes de la Seine autour de Boulogne, Suresnes, Asnières ou Gennevilliers. Le fleuve dessine îles, quais, ports et quartiers d'affaires. Dans ce département très dense, la géographie reste d'abord une affaire de méandres et de berges.", 1, "commune", "pédagogique", "Institut Paris Région", "seine-92"],
  ["92", "géographie", "Le Mont-Valérien relief", "Le Mont-Valérien forme l'un des reliefs les plus visibles de l'ouest parisien. Sa hauteur explique son rôle militaire, religieux et mémoriel. Dans les Hauts-de-Seine, quelques dizaines de mètres d'altitude suffisent à créer un belvédère stratégique sur Paris et la Seine.", 2, "commune", "neutre", "Mémorial de la France combattante", "relief-mont-valerien"],
  ["92", "géographie", "Les coteaux de Meudon", "Les coteaux de Meudon dominent la Seine et offrent des vues rares dans un département très construit. Forêts, carrières anciennes et observatoire y composent un paysage de hauteur. Les Hauts-de-Seine ne sont pas plats : ils cachent des pentes, des bois et des terrasses.", 2, "commune", "poétique", "Office national des forêts", "coteaux-meudon"],
  ["92", "géographie", "Le port de Gennevilliers", "Le port de Gennevilliers est l'un des grands ports fluviaux d'Île-de-France. Conteneurs, matériaux et logistique y donnent une géographie productive très puissante. Dans les Hauts-de-Seine, la Seine reste un axe économique majeur. Le fait ajoute une memoire locale precise. Le repere reste simple et concret.", 2, "commune", "pédagogique", "HAROPA Port", "port-gennevilliers"],
  ["92", "géographie", "La densité de petite couronne", "Les Hauts-de-Seine comptent parmi les départements français les plus densément urbanisés. Cette concentration rapproche logements, bureaux, transports, parcs et berges dans un espace réduit. La géographie du département se comprend donc par la proximité permanente, plus que par la distance.", 1, "commune", "pédagogique", "INSEE", "densite-92"],
  ["92", "gastronomie", "La brioche de Nanterre", "La brioche dite de Nanterre se reconnaît à ses boules alignées dans un moule rectangulaire. Le nom garde une attache locale devenue classique en pâtisserie française. Dans les Hauts-de-Seine, une ville très urbaine possède ainsi une douceur boulangère entrée dans les manuels.", 2, "commune", "surprenant", "Institut national de la boulangerie-pâtisserie", "brioche-nanterre"],
  ["92", "gastronomie", "La vigne de Suresnes", "Suresnes conserve une vigne urbaine sur les pentes du Mont-Valérien. Cette présence surprend dans un département associé aux bureaux et aux transports. Les Hauts-de-Seine rappellent ainsi que l'ouest parisien fut aussi un paysage de coteaux, de vin et de cultures.", 2, "commune", "surprenant", "Ville de Suresnes", "vigne-suresnes"],
  ["92", "gastronomie", "Les marchés de petite couronne", "Les marchés des Hauts-de-Seine, de Neuilly à Antony ou Boulogne, montrent une gastronomie urbaine faite de produits venus d'ailleurs, d'étals spécialisés et de cuisines familiales. Le département n'a pas une seule recette dominante : il mange à l'échelle métropolitaine. La scene devient plus facile a situer.", 3, "peu commune", "pédagogique", "Hauts-de-Seine Tourisme", "marches-92"],
  ["92", "gastronomie", "Les guinguettes de Seine", "Les bords de Seine ont longtemps accueilli restaurants, guinguettes et lieux de sortie. Cette culture du repas au bord de l'eau a précédé les immeubles de bureaux. Dans les Hauts-de-Seine, manger dehors raconte aussi une histoire de loisirs populaires et de fleuve.", 3, "peu commune", "neutre", "Archives départementales des Hauts-de-Seine", "guinguettes-seine-92"],
  ["92", "gastronomie", "Le miel urbain", "Des ruchers urbains existent dans plusieurs communes des Hauts-de-Seine, profitant des parcs, jardins et alignements d'arbres. Cette production modeste raconte une autre lecture de la ville. Le département prouve que la densité n'empêche pas totalement une petite gastronomie de proximité.", 3, "peu commune", "surprenant", "Hauts-de-Seine Tourisme", "miel-urbain-92"],
  ["92", "culture", "La Seine Musicale", "La Seine Musicale, installée sur l'île Seguin, symbolise la reconversion culturelle d'un ancien site industriel. Concerts, auditorium et architecture contemporaine remplacent les chaînes Renault. Dans les Hauts-de-Seine, une île ouvrière devient une grande scène métropolitaine. Cette note renforce son ancrage culturel.", 1, "commune", "neutre", "La Seine Musicale", "seine-musicale"],
  ["92", "culture", "Le musée Albert-Kahn", "Le musée Albert-Kahn à Boulogne-Billancourt conserve des Archives de la planète et des jardins remarquables. Photographies, films et paysages y racontent une curiosité mondiale. Dans les Hauts-de-Seine, une collection locale ouvre sur les cultures du monde entier. Le lieu devient moins abstrait pour le joueur.", 1, "commune", "pédagogique", "Musée départemental Albert-Kahn", "albert-kahn"],
  ["92", "culture", "Rodin à Meudon", "La villa des Brillants à Meudon fut la maison d'Auguste Rodin. Le site permet de relier l'œuvre du sculpteur à un lieu de vie et d'atelier. Dans les Hauts-de-Seine, l'art monumental garde une dimension domestique, presque tranquille, au-dessus de la Seine.", 2, "commune", "neutre", "Musée Rodin - Meudon", "rodin-meudon"],
  ["92", "culture", "La Défense et l'art public", "La Défense possède une importante collection d'œuvres d'art installées sur la dalle et entre les tours. Sculptures monumentales, fontaines et formes colorées changent la lecture du quartier. Dans les Hauts-de-Seine, l'espace d'affaires fonctionne aussi comme un musée à ciel ouvert.", 2, "commune", "surprenant", "Paris La Défense", "art-defense"],
  ["92", "culture", "Le domaine de Sceaux", "Le domaine de Sceaux associe parc classique, musée, collections régionales et grands événements. Il offre une respiration patrimoniale dans un territoire très dense. Les Hauts-de-Seine y montrent une culture de jardin, d'histoire et de promenade, à quelques stations de Paris.", 1, "commune", "neutre", "Domaine départemental de Sceaux", "sceaux-culture"],
  ["92", "insolite", "Un cimetière pour chiens", "Le cimetière des chiens d'Asnières-sur-Seine, ouvert à la fin du XIXe siècle, surprend par ses monuments dédiés aux animaux. Il raconte une histoire affective et urbaine très particulière. Dans les Hauts-de-Seine, même la mémoire funéraire peut prendre une forme inattendue.", 2, "commune", "surprenant", "Ville d'Asnières-sur-Seine", "cimetiere-chiens"],
  ["92", "insolite", "Une vigne entre les immeubles", "La vigne de Suresnes étonne parce qu'elle subsiste dans un environnement très urbanisé, face à Paris et à La Défense. Elle rappelle un passé viticole presque effacé. Dans les Hauts-de-Seine, quelques rangs de vigne suffisent à décaler tout le paysage.", 2, "commune", "surprenant", "Ville de Suresnes", "vigne-insolite"],
  ["92", "insolite", "La Défense n'est pas Paris", "La Défense est souvent perçue comme un morceau de Paris, mais le quartier se situe surtout dans les Hauts-de-Seine, entre Courbevoie, Puteaux et Nanterre. Cette confusion est révélatrice. Le département porte une partie majeure de l'image internationale de la capitale.", 1, "commune", "pédagogique", "Paris La Défense", "defense-pas-paris"],
  ["92", "insolite", "Une tour aux figures", "La Tour aux figures de Jean Dubuffet, sur l'île Saint-Germain, ressemble à une sculpture habitée aux formes colorées. Son apparence tranche avec les immeubles et les berges voisines. Dans les Hauts-de-Seine, l'art public peut prendre une forme presque labyrinthique. Le point complete la scene sans l'alourdir.", 2, "commune", "surprenant", "Département des Hauts-de-Seine", "tour-aux-figures"],
  ["92", "insolite", "Un palais disparu", "Le parc de Saint-Cloud conserve les traces d'un château détruit, sans que le bâtiment principal existe encore. Le vide devient presque un monument. Dans les Hauts-de-Seine, l'insolite tient parfois à visiter un domaine où l'absence raconte autant que les façades.", 3, "peu commune", "poétique", "Domaine national de Saint-Cloud", "palais-disparu"],

  ["93", "histoire", "Saint-Denis et les rois", "La basilique de Saint-Denis abrite les tombeaux de nombreux rois et reines de France. Ce lieu donne à la Seine-Saint-Denis une place centrale dans l'histoire monarchique. Le contraste est fort entre l'image contemporaine du département et cette nécropole royale majeure.", 1, "commune", "pédagogique", "Basilique cathédrale de Saint-Denis", "saint-denis-rois"],
  ["93", "histoire", "Drancy et la déportation", "La cité de la Muette à Drancy fut utilisée comme camp d'internement avant la déportation de nombreux Juifs de France. Le mémorial rappelle cette histoire difficile. En Seine-Saint-Denis, la mémoire de la Shoah se trouve dans un paysage urbain ordinaire, ce qui la rend encore plus saisissante.", 1, "commune", "neutre", "Mémorial de la Shoah de Drancy", "drancy-deportation"],
  ["93", "histoire", "Le Bourget aéronautique", "Le Bourget est lié à l'histoire de l'aviation, des grands raids aériens aux salons internationaux. Son musée conserve avions, prototypes et récits de vol. En Seine-Saint-Denis, le ciel a autant compté que les usines et les voies ferrées. Le contexte rend le paysage plus lisible.", 1, "commune", "neutre", "Musée de l'Air et de l'Espace", "bourget-aviation"],
  ["93", "histoire", "Les murs à pêches", "Les murs à pêches de Montreuil rappellent une technique horticole qui permettait de produire des fruits réputés près de Paris. Les murs emmagasinaient la chaleur et protégeaient les arbres. En Seine-Saint-Denis, l'agriculture fine a précédé l'urbanisation dense. Le fait ajoute une memoire locale precise.", 2, "commune", "surprenant", "Fédération des murs à pêches", "murs-peches"],
  ["93", "histoire", "La Plaine industrielle", "La Plaine Saint-Denis fut un immense territoire d'usines, d'entrepôts et de voies ferrées avant sa reconversion. Cette histoire ouvrière a façonné l'identité du département. En Seine-Saint-Denis, les grands projets récents reposent souvent sur un passé industriel très dense. Cette nuance donne plus d'epaisseur au lieu.", 2, "commune", "pédagogique", "Archives départementales de Seine-Saint-Denis", "plaine-industrielle"],
  ["93", "histoire", "Bobigny et le procès de 1972", "Le procès de Bobigny en 1972, autour de l'avortement, devient un moment important du combat pour les droits des femmes. Il précède la loi Veil. En Seine-Saint-Denis, un tribunal local est devenu une scène nationale de transformation sociale. Le recit gagne ainsi une accroche immediate.", 2, "commune", "pédagogique", "Archives départementales de Seine-Saint-Denis", "proces-bobigny"],
  ["93", "histoire", "Saint-Ouen et les Puces", "Les Puces de Saint-Ouen se développent aux portes de Paris et deviennent un immense marché d'antiquités, de brocante et d'objets. Cette histoire commerciale donne au département une culture de récupération et de circulation. La Seine-Saint-Denis y transforme la marge urbaine en destination mondiale.", 1, "commune", "neutre", "Marché aux Puces de Saint-Ouen", "puces-saint-ouen"],
  ["93", "histoire", "Le canal de l'Ourcq", "Le canal de l'Ourcq a structuré l'est parisien et plusieurs communes de Seine-Saint-Denis. Il a transporté eau, matériaux et marchandises, avant de devenir aussi un espace de loisirs. Le département conserve là une infrastructure qui relie histoire industrielle et usages contemporains.", 2, "commune", "pédagogique", "Ville de Paris - Canaux", "canal-ourcq"],
  ["93", "histoire", "Noisy-le-Grand et les Arènes", "Les espaces d'Abraxas à Noisy-le-Grand, conçus par Ricardo Bofill, témoignent d'une ambition architecturale forte des années 1980. Ce grand décor résidentiel a marqué l'imaginaire visuel. En Seine-Saint-Denis, le logement social peut devenir une architecture spectaculaire. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "Ville de Noisy-le-Grand", "abraxas"],
  ["93", "histoire", "Le Stade de France", "Le Stade de France est construit à Saint-Denis pour la Coupe du monde de football 1998. Il transforme l'image du nord parisien et accompagne la reconversion de la Plaine. En Seine-Saint-Denis, un équipement sportif devient un symbole national et urbain.", 1, "commune", "neutre", "Stade de France", "stade-france"],
  ["93", "géographie", "La Plaine Saint-Denis", "La Plaine Saint-Denis est un espace plat, longtemps industriel, situé entre Paris et Saint-Denis. Sa reconversion concentre bureaux, studios, logements et grands équipements. En Seine-Saint-Denis, la géographie la plus visible est parfois celle d'un sol réutilisé, reconstruit et densifié. Cette note renforce son ancrage culturel.", 1, "commune", "pédagogique", "Plaine Commune", "plaine-saint-denis"],
  ["93", "géographie", "L'Ourcq axe urbain", "Le canal de l'Ourcq traverse la Seine-Saint-Denis comme un ruban d'eau très urbain. Il relie parcs, friches, quartiers populaires et nouvelles promenades. Le département y montre une géographie de reconquête, où une infrastructure technique devient un paysage partagé. Le lieu devient moins abstrait pour le joueur.", 1, "commune", "neutre", "Ville de Paris - Canaux", "ourcq-geographie"],
  ["93", "géographie", "Le parc Georges-Valbon", "Le parc Georges-Valbon, à La Courneuve, est l'un des grands espaces verts de la petite couronne. Ses plans d'eau, pelouses et chemins offrent une respiration considérable. En Seine-Saint-Denis, la nature urbaine n'est pas minuscule : elle peut prendre une échelle métropolitaine.", 1, "commune", "surprenant", "Département de Seine-Saint-Denis", "georges-valbon"],
  ["93", "géographie", "Le plateau de Montreuil", "Montreuil occupe un plateau qui a favorisé jardins, carrières, murs à pêches puis urbanisation. Cette géographie de hauteur explique une partie des vues et des microclimats locaux. En Seine-Saint-Denis, même les reliefs modestes ont produit des usages très spécifiques. Le detail fait mieux sentir le terrain.", 2, "commune", "pédagogique", "Ville de Montreuil", "plateau-montreuil"],
  ["93", "géographie", "La densité populaire", "La Seine-Saint-Denis est l'un des départements les plus denses et les plus jeunes de France métropolitaine. Cette concentration façonne transports, logements, écoles, parcs et cultures urbaines. Sa géographie humaine compte autant que ses rivières ou ses reliefs, parce qu'elle transforme chaque espace disponible.", 1, "commune", "pédagogique", "INSEE", "densite-93"],
  ["93", "gastronomie", "Les pêches de Montreuil", "Les pêches de Montreuil furent longtemps réputées grâce aux murs qui créaient un microclimat favorable. Cette spécialité horticole surprend dans un département aujourd'hui très urbanisé. La Seine-Saint-Denis garde ainsi une mémoire fruitière fine, attachée à des jardins et à un savoir-faire précis.", 2, "commune", "surprenant", "Fédération des murs à pêches", "peches-montreuil"],
  ["93", "gastronomie", "Les marchés de Saint-Denis", "Les marchés de Saint-Denis racontent une gastronomie populaire et métissée, faite d'épices, de produits frais et de cuisines familiales. On y lit les migrations autant que les saisons. En Seine-Saint-Denis, manger local signifie souvent rencontrer plusieurs mondes dans la même allée.", 2, "commune", "neutre", "Ville de Saint-Denis", "marches-saint-denis"],
  ["93", "gastronomie", "Les Puces et les cafés", "Autour des Puces de Saint-Ouen, cafés, petits restaurants et comptoirs accompagnent depuis longtemps la chine et la balade. Cette culture de pause fait partie du lieu. En Seine-Saint-Denis, la gastronomie peut être liée au commerce d'objets autant qu'à un produit de terroir.", 3, "peu commune", "neutre", "Marché aux Puces de Saint-Ouen", "puces-cafes"],
  ["93", "gastronomie", "La cuisine du monde", "La Seine-Saint-Denis concentre des cuisines venues d'Afrique, d'Asie, d'Europe et des Caraïbes, visibles dans ses commerces et restaurants. Cette diversité n'est pas un slogan : elle se mange au quotidien. Le département transforme la métropole en carte gustative très vivante.", 1, "commune", "pédagogique", "Seine-Saint-Denis Tourisme", "cuisine-monde-93"],
  ["93", "gastronomie", "Les brasseries urbaines", "Des brasseries artisanales se sont installées dans plusieurs communes de Seine-Saint-Denis, souvent dans d'anciens espaces industriels ou artisanaux. Elles accompagnent la reconversion du territoire. Le département y montre une gastronomie urbaine récente, liée aux friches, aux quartiers et aux nouvelles sociabilités.", 3, "peu commune", "neutre", "Seine-Saint-Denis Tourisme", "brasseries-93"],
  ["93", "culture", "Le Stade de France culturel", "Le Stade de France accueille concerts, ceremonies et grands rassemblements qui donnent une dimension culturelle majeure. Sa silhouette est devenue un repère collectif. En Seine-Saint-Denis, un équipement né pour 1998 fonctionne comme scène nationale polyvalente. Le repere reste simple et concret.", 1, "commune", "neutre", "Stade de France", "stade-culture"],
  ["93", "culture", "La MC93", "La MC93 à Bobigny est une grande scène de théâtre, danse et création contemporaine. Elle incarne une ambition culturelle forte en banlieue parisienne. En Seine-Saint-Denis, la création artistique ne se contente pas de rayonner depuis Paris : elle possède ses propres lieux majeurs.", 2, "commune", "neutre", "MC93", "mc93"],
  ["93", "culture", "Banlieues Bleues", "Le festival Banlieues Bleues fait circuler jazz et musiques improvisées dans plusieurs villes du département. Il relie scènes, publics et territoires depuis des décennies. En Seine-Saint-Denis, la culture musicale se construit aussi par le déplacement, la rencontre et l'invention collective.", 2, "commune", "neutre", "Banlieues Bleues", "banlieues-bleues"],
  ["93", "culture", "Le street art de l'Ourcq", "Les abords du canal de l'Ourcq accueillent fresques, interventions graphiques et parcours urbains. Cette culture visuelle accompagne la transformation des berges et des friches. En Seine-Saint-Denis, l'art se lit souvent directement sur les murs, à hauteur de promenade. Le fait ajoute une memoire locale precise.", 2, "commune", "surprenant", "Seine-Saint-Denis Tourisme", "street-art-ourcq"],
  ["93", "culture", "Le musée de l'Air", "Le musée de l'Air et de l'Espace du Bourget conserve avions, fusées, nacelles et récits d'exploration. Il donne au département une culture technique très spectaculaire. En Seine-Saint-Denis, le patrimoine industriel dialogue aussi avec le ciel : il s'élève aussi vers le ciel.", 1, "commune", "pédagogique", "Musée de l'Air et de l'Espace", "musee-air"],
  ["93", "insolite", "Des rois en Seine-Saint-Denis", "La présence des tombeaux royaux à Saint-Denis surprend ceux qui réduisent le département à son image contemporaine. La nécropole capétienne se trouve bien en Seine-Saint-Denis. Ce décalage fait du 93 un territoire où la monarchie française côtoie la banlieue moderne.", 1, "commune", "surprenant", "Basilique cathédrale de Saint-Denis", "rois-93"],
  ["93", "insolite", "Les Puces géantes", "Les Puces de Saint-Ouen forment l'un des plus grands ensembles de marchés d'antiquités et de brocante au monde. On peut y passer des heures entre meubles, affiches, vêtements et objets improbables. En Seine-Saint-Denis, la seconde main devient une aventure urbaine.", 1, "commune", "surprenant", "Marché aux Puces de Saint-Ouen", "puces-geantes"],
  ["93", "insolite", "Un aéroport musée", "Le Bourget est à la fois un aéroport d'affaires, un lieu de salons aéronautiques et un grand musée de l'aviation. Cette superposition donne une ambiance particulière. En Seine-Saint-Denis, les avions deviennent patrimoine, spectacle et memoire technique. Le repere reste simple et concret.", 2, "commune", "surprenant", "Musée de l'Air et de l'Espace", "bourget-insolite"],
  ["93", "insolite", "Des pêches derrière les murs", "Les murs à pêches de Montreuil racontent une agriculture presque invisible depuis la rue. Derrière des murs ordinaires se cachait un système horticole très élaboré. En Seine-Saint-Denis, l'insolite vient de cette mémoire agricole enfouie dans la ville dense. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "Fédération des murs à pêches", "peches-insolite"],
  ["93", "insolite", "Abraxas décor de cinéma", "Les Espaces d'Abraxas à Noisy-le-Grand ont servi de décor à plusieurs tournages grâce à leur architecture monumentale. Le lieu semble parfois plus proche d'une cité imaginaire que d'un ensemble résidentiel. En Seine-Saint-Denis, l'urbanisme devient facilement science-fiction. Le territoire y gagne une couleur nette.", 2, "commune", "surprenant", "Ville de Noisy-le-Grand", "abraxas-cinema"],
  ["94", "histoire", "Le donjon de Vincennes", "Le château de Vincennes conserve un donjon royal impressionnant, commencé au XIVe siècle. Il rappelle que l'actuel Val-de-Marne touche à une histoire de pouvoir très ancienne. Derrière les boulevards et les lignes de métro, Vincennes garde la silhouette d'une résidence fortifiée des rois de France.", 2, "commune", "neutre", "Château de Vincennes", "vincennes-donjon"],
  ["94", "histoire", "Rungis remplace les Halles", "En 1969, le marché de Rungis prend le relais des anciennes Halles de Paris. Le déménagement change l'échelle de l'approvisionnement alimentaire francilien. Dans le Val-de-Marne, ce transfert transforme un territoire de banlieue en point névralgique de la logistique fraîche. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "surprenant", "Marché International de Rungis", "rungis-halles"],
  ["94", "histoire", "L'école vétérinaire d'Alfort", "L'École nationale vétérinaire d'Alfort est fondée au XVIIIe siècle et reste l'une des grandes institutions scientifiques du département. Elle associe formation, recherche et collections étonnantes. À Maisons-Alfort, l'histoire vétérinaire donne au Val-de-Marne un visage savant et discret. La reference garde une portee tres locale.", 3, "peu commune", "neutre", "École nationale vétérinaire d'Alfort", "alfort-veterinaire"],
  ["94", "histoire", "Les guinguettes de la Marne", "Les bords de Marne attirent longtemps Parisiens, canotiers et danseurs du dimanche. Joinville, Nogent et Champigny deviennent des lieux de loisirs populaires. Cette histoire donne au Val-de-Marne une mémoire joyeuse, liée aux promenades, aux bals et aux restaurants au bord de l'eau.", 2, "commune", "amusant", "Archives départementales du Val-de-Marne", "guinguettes-marne"],
  ["94", "histoire", "Champigny en 1870", "Pendant la guerre de 1870, Champigny-sur-Marne est le théâtre de combats importants lors du siège de Paris. Le nom de la ville reste attaché à cette tentative de sortie. Dans le Val-de-Marne, la mémoire militaire surgit parfois au détour d'une commune très résidentielle.", 3, "peu commune", "neutre", "Archives départementales du Val-de-Marne", "champigny-1870"],
  ["94", "histoire", "Joinville côté cinéma", "Au XXe siècle, les studios de Joinville participent à l'histoire du cinéma français. Des tournages, des plateaux et des métiers techniques s'y concentrent. Le Val-de-Marne garde ainsi une part de mémoire de studio, entre industrie culturelle et banlieue des bords de Marne.", 3, "peu commune", "neutre", "Ville de Joinville-le-Pont", "joinville-cinema"],
  ["94", "histoire", "Créteil devient préfecture", "La création du Val-de-Marne en 1968 donne à Créteil un rôle administratif majeur. La ville se transforme avec la préfecture, l'université, le lac et de grands équipements. Cette histoire récente rappelle que les départements franciliens ont aussi été dessinés par l'aménagement moderne.", 2, "commune", "pédagogique", "Préfecture du Val-de-Marne", "creteil-prefecture"],
  ["94", "histoire", "Ivry rouge et ouvrière", "Ivry-sur-Seine garde une forte mémoire ouvrière et municipale. Usines, logements populaires et engagement politique ont longtemps marqué son paysage. Le Val-de-Marne ne se réduit pas à une banlieue résidentielle : il porte aussi l'histoire sociale dense de la petite couronne.", 3, "peu commune", "neutre", "Ville d'Ivry-sur-Seine", "ivry-ouvrier"],
  ["94", "histoire", "L'aqueduc d'Arcueil", "À Arcueil et Cachan, les arches de l'aqueduc rappellent l'importance ancienne de l'eau pour Paris. Plusieurs ouvrages s'y superposent au fil des siècles. Cette présence monumentale donne au Val-de-Marne une histoire technique visible, posée au-dessus des rues et des vallées.", 3, "peu commune", "neutre", "Ville d'Arcueil", "arcueil-aqueduc"],
  ["94", "histoire", "Vitry et l'art urbain", "Vitry-sur-Seine s'est imposée comme un terrain majeur de l'art urbain en Île-de-France. Fresques, murs peints et interventions d'artistes accompagnent l'espace quotidien. Dans le Val-de-Marne, cette culture transforme des façades ordinaires en repères visuels puissants. L'ensemble devient plus vivant et situe.", 2, "commune", "surprenant", "Ville de Vitry-sur-Seine", "vitry-street-art"],
  ["94", "géographie", "La rencontre Seine-Marne", "Le Val-de-Marne doit une partie de son identité à la rencontre entre la Seine et la Marne, près de Charenton et d'Alfortville. Cette confluence structure les circulations et les paysages. Dans un département très urbain, l'eau reste une clé de lecture essentielle.", 2, "commune", "neutre", "Institut Paris Région", "confluence-seine-marne"],
  ["94", "géographie", "Les boucles de la Marne", "La Marne dessine des boucles généreuses autour de Saint-Maur, Joinville ou Champigny. Ces courbes ont créé des îles, des promenades et des quartiers tournés vers l'eau. Le Val-de-Marne garde ainsi une géographie fluviale très lisible malgré la densité urbaine. Cette precision ancre mieux le recit territorial.", 2, "commune", "poétique", "Département du Val-de-Marne", "boucles-marne"],
  ["94", "géographie", "La Bièvre disparue", "La Bièvre traverse une partie du Val-de-Marne, souvent cachée ou canalisée. Son histoire raconte la transformation des petites rivières urbaines en réseaux invisibles. À Gentilly, Arcueil ou Cachan, la géographie se lit parfois dans ce qui ne se voit plus.", 3, "peu commune", "surprenant", "Syndicat mixte du bassin versant de la Bièvre", "bievre-cachee"],
  ["94", "géographie", "Le plateau de Villejuif", "Autour de Villejuif, le relief forme un plateau dominant la vallée de la Seine et les communes voisines. Ce léger dénivelé compte dans l'histoire des routes, des vues et des implantations urbaines. Le Val-de-Marne n'est pas plat : il alterne vallées, coteaux et plateaux.", 2, "commune", "pédagogique", "Institut Paris Région", "plateau-villejuif"],
  ["94", "géographie", "Des îles dans la ville", "Le Val-de-Marne compte plusieurs îles liées à la Seine ou à la Marne, comme l'île Sainte-Catherine ou l'île des Loups. Elles donnent au département des respirations inattendues. Au milieu de la métropole, la géographie fluviale crée encore des refuges et des détours.", 2, "commune", "poétique", "Département du Val-de-Marne", "iles-marne-seine"],
  ["94", "gastronomie", "Rungis avant l'aube", "Le marché de Rungis vit surtout quand beaucoup dorment encore. Poissons, viandes, fleurs, fruits et légumes y circulent à une cadence impressionnante. Pour le Val-de-Marne, la gastronomie commence souvent dans cette organisation invisible qui nourrit restaurants, marchés et cuisines d'Île-de-France.", 2, "commune", "surprenant", "Marché International de Rungis", "rungis-aube"],
  ["94", "gastronomie", "Les tables des bords de Marne", "Les guinguettes ont associé les bords de Marne à une cuisine de dimanche : fritures, vins simples, terrasses et bals. Cette tradition reste un imaginaire gourmand du Val-de-Marne. Elle relie la gastronomie à la promenade, au vélo et aux loisirs populaires.", 2, "commune", "amusant", "Comité départemental du tourisme du Val-de-Marne", "tables-marne"],
  ["94", "gastronomie", "Choisy et les saveurs asiatiques", "Choisy-le-Roi, Ivry et Vitry accueillent de nombreux commerces et restaurants asiatiques. Cette présence a profondément enrichi les habitudes alimentaires locales. Dans le Val-de-Marne, la gastronomie raconte aussi les migrations, les marchés de quartier et les cuisines familiales devenues très populaires.", 2, "commune", "neutre", "Comité départemental du tourisme du Val-de-Marne", "saveurs-asiatiques"],
  ["94", "gastronomie", "Le MIN des fromages", "À Rungis, le secteur des produits laitiers voit passer une variété considérable de fromages. Le lieu n'est pas une ferme, mais il concentre une France entière de terroirs. Le Val-de-Marne devient ainsi un carrefour gourmand plutôt qu'un territoire de production classique.", 2, "commune", "surprenant", "Marché International de Rungis", "rungis-fromages"],
  ["94", "gastronomie", "Les marchés de Créteil", "Les marchés de Créteil et des communes voisines reflètent une cuisine très métissée. Produits franciliens, spécialités méditerranéennes, épices et pains du monde s'y côtoient. Dans le Val-de-Marne, l'identité culinaire naît souvent de cette densité humaine et commerçante. Le territoire y gagne une couleur nette.", 2, "commune", "neutre", "Ville de Créteil", "marches-creteil"],
  ["94", "culture", "Le MAC VAL à Vitry", "Le MAC VAL, ouvert à Vitry-sur-Seine, est le premier musée d'art contemporain créé par un département en France. Il installe une grande institution culturelle hors du centre parisien. Le Val-de-Marne affirme ainsi une culture de proximité, ambitieuse et très ancrée dans la banlieue.", 2, "commune", "neutre", "MAC VAL", "mac-val"],
  ["94", "culture", "Le musée Fragonard", "À Maisons-Alfort, le musée Fragonard conserve des collections vétérinaires étonnantes, parfois très impressionnantes. Il transforme l'histoire scientifique en expérience culturelle rare. Le Val-de-Marne y montre une facette inattendue, entre anatomie, enseignement et curiosité muséale. Le lieu devient moins abstrait pour le joueur.", 3, "rare", "surprenant", "Musée Fragonard", "musee-fragonard"],
  ["94", "culture", "La maison Robert Doisneau", "À Gentilly, la Maison de la photographie Robert Doisneau défend une photographie humaniste et documentaire. Le lieu prolonge un regard attentif aux rues, aux gestes et aux gens. Dans le Val-de-Marne, l'image devient une manière sensible de lire la banlieue.", 2, "commune", "poétique", "Maison de la photographie Robert Doisneau", "doisneau-gentilly"],
  ["94", "culture", "Le théâtre de la Cartoucherie", "À Vincennes, la Cartoucherie rassemble plusieurs théâtres dans un ancien site militaire du bois. Le lieu est associé notamment au Théâtre du Soleil. Le Val-de-Marne accueille ici une culture de troupe, de scène et d'expérimentation très reconnaissable. Le detail fait mieux sentir le terrain.", 2, "commune", "neutre", "La Cartoucherie de Vincennes", "cartoucherie-vincennes"],
  ["94", "culture", "Créteil et le cinéma de femmes", "Le Festival international de films de femmes de Créteil existe depuis la fin des années 1970. Il met en avant des réalisatrices et des regards longtemps moins visibles. Dans le Val-de-Marne, le cinéma sert aussi de lieu de débat et de mémoire culturelle.", 3, "peu commune", "neutre", "Festival Films de Femmes Créteil", "festival-femmes-creteil"],
  ["94", "insolite", "Chinagora sur la Seine", "À Alfortville, Chinagora dresse ses toits chinois au bord de la Seine. Le bâtiment tranche fortement avec le paysage urbain environnant. Cette silhouette inattendue donne au Val-de-Marne un repère visuel singulier, entre hôtel, symbole architectural et décor presque cinématographique. Le paysage prend alors une presence nette.", 2, "commune", "surprenant", "Ville d'Alfortville", "chinagora"],
  ["94", "insolite", "Le lac de Créteil artificiel", "Le lac de Créteil est né d'anciennes carrières exploitées pour l'aménagement urbain. Il est devenu un élément central de la ville nouvelle. Dans le Val-de-Marne, un paysage de loisirs peut donc venir d'une transformation très technique du sol. Le recit reste court, mais plus incarne.", 2, "commune", "surprenant", "Ville de Créteil", "lac-creteil"],
  ["94", "insolite", "Le cimetière des chiens", "À Asnières se trouve le célèbre cimetière des chiens, mais le Val-de-Marne possède aussi une forte mémoire animalière avec l'école d'Alfort. Cette anecdote crée un écho amusant autour des animaux en petite couronne. Maisons-Alfort reste surtout le grand repère vétérinaire du département.", 2, "commune", "amusant", "École nationale vétérinaire d'Alfort", "alfort-animaux"],
  ["94", "insolite", "Une rivière sous les pieds", "Dans plusieurs communes du Val-de-Marne, la Bièvre passe sous terre ou dans des tracés difficiles à deviner. On marche parfois au-dessus d'une rivière oubliée. Cette présence cachée donne au territoire une dimension secrète, très éloignée de l'image d'une banlieue entièrement minérale.", 3, "peu commune", "surprenant", "Syndicat mixte du bassin versant de la Bièvre", "bievre-insolite"],
  ["94", "insolite", "Les arches dans la ville", "À Arcueil, l'aqueduc traverse le paysage urbain avec une puissance inhabituelle. Ses arches semblent découper la ville comme un décor antique, alors qu'elles servent une histoire très concrète de l'eau. Le Val-de-Marne sait parfois mélanger monumental et quotidien. L'ensemble devient plus vivant et situe.", 2, "commune", "surprenant", "Ville d'Arcueil", "arches-arcueil"],
  ["95", "histoire", "Auvers et Van Gogh", "Vincent van Gogh passe les dernières semaines de sa vie à Auvers-sur-Oise en 1890. Le village devient l'un des lieux majeurs de sa mémoire française. Dans le Val-d'Oise, l'histoire de l'art se concentre autour d'une présence brève, intense et devenue universelle.", 2, "commune", "neutre", "Office de tourisme d'Auvers-sur-Oise", "auvers-van-gogh"],
  ["95", "histoire", "Pontoise ville médiévale", "Pontoise fut une ville importante du royaume capétien, avec un pont, un marché et des fortifications. Son relief au-dessus de l'Oise explique une partie de son rôle. Le Val-d'Oise garde là un centre ancien où l'histoire urbaine précède largement la banlieue moderne.", 2, "commune", "neutre", "Ville de Pontoise", "pontoise-medievale"],
  ["95", "histoire", "L'abbaye de Royaumont", "Fondée par Saint Louis au XIIIe siècle, l'abbaye de Royaumont reste l'un des grands sites patrimoniaux du Val-d'Oise. Ses bâtiments racontent à la fois la vie monastique, les transformations du temps et une reconversion culturelle. Le lieu relie mémoire royale et création contemporaine.", 2, "commune", "neutre", "Fondation Royaumont", "royaumont-abbaye"],
  ["95", "histoire", "La Roche-Guyon frontière", "La Roche-Guyon occupe un site spectaculaire entre falaise, château et vallée de Seine. Son histoire tient beaucoup à cette position de contrôle. Dans le Val-d'Oise, ce village rappelle que le département touche aussi au Vexin, aux routes anciennes et aux paysages défensifs.", 3, "peu commune", "neutre", "Château de La Roche-Guyon", "la-roche-guyon"],
  ["95", "histoire", "Enghien ville d'eaux", "Enghien-les-Bains se développe au XIXe siècle autour de ses eaux sulfureuses, de son lac et de ses établissements de loisirs. La ville donne au Val-d'Oise une image thermale rare en Île-de-France. Santé, promenade et divertissement s'y mêlent dans un décor très urbain.", 2, "commune", "surprenant", "Ville d'Enghien-les-Bains", "enghien-thermal"],
  ["95", "histoire", "Roissy devient mondial", "Le village de Roissy-en-France change d'échelle avec le développement de l'aéroport Paris-Charles-de-Gaulle. Le Val-d'Oise se retrouve lié aux flux internationaux, aux hôtels et à la logistique. Cette histoire récente montre comment une infrastructure peut redessiner tout un territoire. Le recit gagne ainsi une accroche immediate.", 2, "commune", "neutre", "Groupe ADP", "roissy-aeroport"],
  ["95", "histoire", "Cergy ville nouvelle", "Cergy-Pontoise fait partie des villes nouvelles conçues pour organiser la croissance francilienne. Préfecture, université, quartiers et grands axes y composent une histoire urbaine récente. Le Val-d'Oise y affirme une identité différente des vieux centres et des villages du Vexin. Ce point eclaire mieux son identite locale.", 2, "commune", "pédagogique", "Communauté d'agglomération de Cergy-Pontoise", "cergy-ville-nouvelle"],
  ["95", "histoire", "Argenteuil impressionniste", "Argenteuil attire Monet et d'autres peintres au XIXe siècle grâce à la Seine, aux voiliers et à la lumière des berges. La ville devient un motif important de l'impressionnisme. Dans le Val-d'Oise, l'industrie et la peinture ont longtemps partagé le même horizon fluvial.", 2, "commune", "neutre", "Ville d'Argenteuil", "argenteuil-impressionniste"],
  ["95", "histoire", "Sarcelles et les grands ensembles", "Sarcelles devient dans les années 1950 et 1960 un symbole des grands ensembles français. Le mot sarcellite a même servi à décrire les inquiétudes liées à cette urbanisation rapide. Dans le Val-d'Oise, l'histoire sociale du logement moderne reste très visible.", 3, "peu commune", "pédagogique", "Ville de Sarcelles", "sarcelles-grands-ensembles"],
  ["95", "histoire", "Maubuisson et les abbesses", "L'abbaye de Maubuisson, fondée au XIIIe siècle, fut un lieu important de pouvoir religieux féminin. Ses bâtiments accueillent aujourd'hui de l'art contemporain. Le Val-d'Oise y montre une continuité rare entre histoire monastique, patrimoine et création actuelle. Le territoire y gagne une couleur nette.", 3, "peu commune", "neutre", "Abbaye de Maubuisson", "maubuisson"],
  ["95", "géographie", "Le Vexin français", "Le Val-d'Oise abrite une grande partie du Vexin français, territoire de plateaux, de villages en pierre et de vallées calmes. Ce paysage contraste fortement avec les zones aéroportuaires et les villes nouvelles. Le département passe ainsi très vite de la métropole à la campagne protégée.", 2, "commune", "poétique", "Parc naturel régional du Vexin français", "vexin"],
  ["95", "géographie", "La vallée de l'Oise", "L'Oise traverse le département et donne son nom au Val-d'Oise. Sa vallée a guidé les villes, les échanges et les paysages industriels ou résidentiels. De Pontoise à L'Isle-Adam, l'eau forme une colonne vertébrale discrète mais essentielle. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "neutre", "Département du Val-d'Oise", "vallee-oise"],
  ["95", "géographie", "Les buttes du Parisis", "Les buttes du Parisis dominent une partie de l'ouest francilien. Elles offrent des vues sur Paris, la Seine et les zones urbaines voisines. Dans le Val-d'Oise, ces reliefs modestes jouent un rôle important pour comprendre les paysages et les limites de la métropole.", 2, "commune", "pédagogique", "Agence des espaces verts d'Île-de-France", "buttes-parisis"],
  ["95", "géographie", "La plaine de France", "Autour de Roissy et de Gonesse, la plaine de France forme un grand espace ouvert, longtemps agricole, désormais marqué par l'aéroport et les zones d'activité. Le Val-d'Oise y montre la tension entre cultures céréalières, urbanisation et grandes infrastructures. Le detail fait mieux sentir le terrain.", 2, "commune", "neutre", "Institut Paris Région", "plaine-france"],
  ["95", "géographie", "La Seine aux portes du Vexin", "À La Roche-Guyon ou Vétheuil, la Seine borde le Val-d'Oise dans un décor de coteaux et de falaises. Ce paysage tranche avec l'image très francilienne du département. Le fleuve donne ici une respiration presque normande aux confins de l'Île-de-France. Cette precision donne un repere sensible.", 2, "commune", "poétique", "Parc naturel régional du Vexin français", "seine-vexin"],
  ["95", "gastronomie", "L'asperge d'Argenteuil", "L'asperge d'Argenteuil fut longtemps une spécialité maraîchère réputée autour de Paris. Sa culture rappelle le passé agricole d'une ville aujourd'hui très urbaine. Dans le Val-d'Oise, la gastronomie garde ainsi la trace de champs qui nourrissaient autrefois la capitale. Le paysage prend alors une presence nette.", 2, "commune", "surprenant", "Ville d'Argenteuil", "asperge-argenteuil"],
  ["95", "gastronomie", "La cerise de Montmorency", "La cerise de Montmorency est associée depuis longtemps aux coteaux du nord de Paris. Elle a donné son nom à une variété connue bien au-delà du Val-d'Oise. Cette petite baie rappelle que le département a possédé une forte tradition fruitière.", 2, "commune", "neutre", "Ville de Montmorency", "cerise-montmorency"],
  ["95", "gastronomie", "Les produits du Vexin", "Le Vexin français met en avant farines, miels, bières et produits fermiers issus de ses plateaux. Cette gastronomie de proximité donne au Val-d'Oise un ancrage rural souvent oublié. À quelques kilomètres de Roissy, les circuits courts gardent une vraie présence.", 2, "commune", "neutre", "Parc naturel régional du Vexin français", "produits-vexin"],
  ["95", "gastronomie", "Les marchés de Pontoise", "Pontoise conserve une tradition de marché liée à son rôle ancien de ville d'échanges. Fruits, légumes, pains et produits du Vexin y rencontrent une clientèle urbaine. Dans le Val-d'Oise, la gastronomie passe souvent par ces lieux de commerce très quotidiens.", 2, "commune", "neutre", "Ville de Pontoise", "marches-pontoise"],
  ["95", "gastronomie", "Enghien côté salons", "Enghien-les-Bains a longtemps associé promenades, cafés et plaisirs de station thermale. Cette sociabilité a façonné une gastronomie de salons, de terrasses et de restaurants autour du lac. Le Val-d'Oise y prend des airs de ville d'eaux très francilienne. L'ensemble devient plus vivant et situe.", 2, "commune", "poétique", "Office de tourisme d'Enghien-les-Bains", "enghien-tables"],
  ["95", "culture", "L'Axe majeur de Cergy", "L'Axe majeur de Cergy, conçu par Dani Karavan, inscrit une grande perspective artistique dans la ville nouvelle. Escaliers, colonnes et vues sur l'Oise composent une promenade monumentale. Dans le Val-d'Oise, l'art public sert ici à donner une identité au paysage urbain.", 2, "commune", "surprenant", "Ville de Cergy", "axe-majeur"],
  ["95", "culture", "Royaumont lieu de musique", "L'abbaye de Royaumont accueille aujourd'hui résidences, concerts et rencontres artistiques. Le site reste un espace de creation autant qu'un monument ancien. Dans le Val-d'Oise, la culture contemporaine dialogue avec les pierres médiévales. Cette precision ancre mieux le recit territorial. Le repere reste simple et concret.", 2, "commune", "neutre", "Fondation Royaumont", "royaumont-musique"],
  ["95", "culture", "Auvers village de peinture", "Auvers-sur-Oise concentre une mémoire picturale très forte autour de Van Gogh, Daubigny, Cézanne et d'autres artistes. Le village a transformé ses paysages en parcours culturel. Dans le Val-d'Oise, la peinture devient presque une manière de visiter les rues. Le contexte rend le paysage plus lisible.", 2, "commune", "poétique", "Office de tourisme d'Auvers-sur-Oise", "auvers-peinture"],
  ["95", "culture", "Maubuisson art contemporain", "L'abbaye de Maubuisson accueille des expositions d'art contemporain dans un ancien cadre cistercien. Le contraste entre installations et architecture monastique donne une expérience particulière. Le Val-d'Oise y affirme une culture qui ne sépare pas patrimoine et création actuelle. Le fait ajoute une memoire locale precise.", 2, "commune", "neutre", "Abbaye de Maubuisson", "maubuisson-art"],
  ["95", "culture", "Le musée archéologique", "À Guiry-en-Vexin, le musée archéologique du Val-d'Oise présente des objets trouvés dans le département. Il rappelle que le Vexin et la vallée de l'Oise sont habités depuis très longtemps. Cette culture matérielle donne de la profondeur aux paysages ruraux. Cette nuance donne plus d'epaisseur au lieu.", 3, "peu commune", "neutre", "Musée archéologique du Val-d'Oise", "musee-archeologique-95"],
  ["95", "insolite", "Le seul casino francilien", "Enghien-les-Bains accueille le principal casino d'Île-de-France, particularité liée à son statut de ville thermale. Cette exception donne au Val-d'Oise une touche de station de loisirs inattendue. À quelques minutes de Paris, le lac, les jeux et les spectacles composent un décor singulier.", 2, "commune", "surprenant", "Ville d'Enghien-les-Bains", "casino-enghien"],
  ["95", "insolite", "Soixante-dix jours à Auvers", "Van Gogh ne passe qu'environ soixante-dix jours à Auvers-sur-Oise, mais cette période a laissé une empreinte immense. Le contraste entre la brièveté du séjour et la force du souvenir est saisissant. Le Val-d'Oise tient là l'une de ses histoires les plus intenses.", 2, "commune", "surprenant", "Office de tourisme d'Auvers-sur-Oise", "van-gogh-70-jours"],
  ["95", "insolite", "La falaise habitée", "À La Roche-Guyon, le château s'adosse à une falaise percée de galeries. Le village semble presque fusionner avec la roche. Dans le Val-d'Oise, cette architecture troglodytique donne une impression très différente des paysages habituels de la banlieue parisienne. La scene devient plus facile a situer.", 2, "commune", "surprenant", "Château de La Roche-Guyon", "falaise-roche-guyon"],
  ["95", "insolite", "Roissy sans avion au départ", "Avant de devenir synonyme d'aéroport international, Roissy-en-France était un village de la plaine de France. Son nom a changé d'échelle avec l'infrastructure voisine. Dans le Val-d'Oise, un toponyme local est devenu un repère mondial du voyage. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "Groupe ADP", "roissy-nom"],
  ["95", "insolite", "Une pyramide en ville nouvelle", "L'Axe majeur de Cergy comprend des formes monumentales qui donnent à la ville nouvelle un air de paysage symbolique. Colonnes, passerelles et perspectives y créent une promenade presque théâtrale. Le Val-d'Oise montre ici qu'un aménagement récent peut devenir un repère insolite.", 2, "commune", "surprenant", "Ville de Cergy", "axe-insolite"],
  ["2A", "histoire", "Ajaccio ville natale de Napoléon", "Napoléon Bonaparte naît à Ajaccio en 1769, quelques mois après le rattachement de la Corse à la France. Sa maison familiale est devenue un lieu de mémoire majeur. En Corse-du-Sud, l'histoire locale croise ainsi très directement l'histoire politique européenne. Cette note renforce son ancrage culturel.", 2, "commune", "neutre", "Maison Bonaparte", "napoleon-ajaccio"],
  ["2A", "histoire", "La citadelle de Bonifacio", "Bonifacio occupe depuis des siècles une position stratégique au-dessus des falaises calcaires. Sa citadelle surveille les Bouches de Bonifacio, passage sensible entre Corse et Sardaigne. En Corse-du-Sud, la géographie a souvent dicté la défense, le commerce et les rivalités maritimes.", 2, "commune", "neutre", "Office de tourisme de Bonifacio", "bonifacio-citadelle"],
  ["2A", "histoire", "Filitosa et les statues-menhirs", "Le site de Filitosa conserve des statues-menhirs parmi les plus célèbres de Corse. Ces silhouettes de pierre donnent accès à une histoire bien antérieure aux citadelles et aux tours génoises. La Corse-du-Sud possède ainsi une profondeur préhistorique très forte. La reference garde une portee tres locale.", 3, "peu commune", "surprenant", "Site préhistorique de Filitosa", "filitosa"],
  ["2A", "histoire", "Les alignements de Cauria", "Autour de Sartène, les alignements de Cauria rassemblent dolmens, menhirs et statues-menhirs. Le paysage semble ouvert sur une mémoire très ancienne. En Corse-du-Sud, la préhistoire ne se cache pas dans un musée : elle affleure dans le maquis et les plateaux.", 3, "peu commune", "poétique", "Collectivité de Corse", "cauria"],
  ["2A", "histoire", "Sartène et le Catenacciu", "À Sartène, la procession du Catenacciu marque la Semaine sainte par une mise en scène religieuse très ancienne. Un pénitent enchaîné traverse la ville dans une ambiance grave. La Corse-du-Sud garde là une tradition spectaculaire, à la fois spirituelle et profondément locale.", 3, "rare", "neutre", "Office de tourisme de Sartène", "catenacciu"],
  ["2A", "histoire", "La Corse libérée en 1943", "La Corse est le premier territoire métropolitain libéré en 1943, après l'insurrection locale et l'arrivée de troupes françaises. La Corse-du-Sud partage cette mémoire de résistance et de combats. L'événement donne à l'île une place particulière dans l'histoire de la Libération.", 3, "peu commune", "pédagogique", "Musée de la Résistance corse", "liberation-corse"],
  ["2A", "histoire", "Les tours génoises du littoral", "Le littoral de Corse-du-Sud conserve plusieurs tours génoises, bâties pour surveiller la mer et alerter les villages. Elles rappellent une époque de menaces venues du large. Ces silhouettes de pierre relient aujourd'hui randonnée, paysage et mémoire défensive. Le recit reste court, mais plus incarne.", 2, "commune", "neutre", "Collectivité de Corse", "tours-genoises-2a"],
  ["2A", "histoire", "Le musée Fesch", "Le musée Fesch d'Ajaccio conserve une importante collection de peintures italiennes, liée au cardinal Fesch, oncle de Napoléon. Le lieu rappelle les liens entre la Corse, l'Italie et l'histoire impériale. En Corse-du-Sud, la culture savante passe aussi par les collections familiales.", 3, "peu commune", "neutre", "Musée Fesch", "musee-fesch"],
  ["2A", "histoire", "Les Bonaparte à Ajaccio", "La famille Bonaparte appartient à la petite noblesse corse avant l'ascension de Napoléon. Sa maison d'Ajaccio montre un monde plus local, familial et insulaire que l'image impériale habituelle. La Corse-du-Sud rappelle ainsi les origines concrètes d'un destin mondial. Le point complete la scene sans l'alourdir.", 2, "commune", "pédagogique", "Maison Bonaparte", "bonaparte-famille"],
  ["2A", "histoire", "L'Alta Rocca fortifiée", "L'Alta Rocca garde des traces de villages perchés, de familles seigneuriales et de chemins anciens. Ce territoire intérieur rappelle que la Corse-du-Sud ne se résume pas à ses ports. Dans la montagne, l'histoire s'est aussi construite autour du contrôle des passages.", 3, "peu commune", "neutre", "Office de tourisme de l'Alta Rocca", "alta-rocca"],
  ["2A", "géographie", "Les falaises de Bonifacio", "Les falaises blanches de Bonifacio forment l'un des paysages les plus reconnaissables de Corse-du-Sud. La ville semble posée au bord du vide, face à la Sardaigne. Ce relief spectaculaire explique autant la beauté du site que son importance stratégique. Le detail donne au lieu une presence plus concrete.", 2, "commune", "poétique", "Office de tourisme de Bonifacio", "falaises-bonifacio"],
  ["2A", "géographie", "Les calanques de Piana", "Les calanques de Piana, près du golfe de Porto, mêlent roches rouges, mer bleue et formes sculptées par l'érosion. Le paysage est inscrit au patrimoine mondial avec le golfe de Girolata et Scandola. La Corse-du-Sud y atteint une intensité visuelle rare.", 2, "commune", "poétique", "UNESCO", "piana"],
  ["2A", "géographie", "Les aiguilles de Bavella", "Les aiguilles de Bavella dressent leurs pics rocheux au-dessus de l'Alta Rocca. Le site relie forêt, montagne et routes sinueuses. En Corse-du-Sud, la géographie intérieure rivalise avec les paysages littoraux et donne au département une dimension alpine inattendue. Le contexte rend le paysage plus lisible.", 2, "commune", "poétique", "Parc naturel régional de Corse", "bavella"],
  ["2A", "géographie", "Les îles Lavezzi", "Les îles Lavezzi forment un archipel granitique entre Corse et Sardaigne. Blocs arrondis, eaux claires et vents forts y composent un paysage très minéral. En Corse-du-Sud, ce bout d'archipel rappelle la fragilité des espaces marins les plus fréquentés. Le fait ajoute une memoire locale precise.", 2, "commune", "neutre", "Réserve naturelle des Bouches de Bonifacio", "lavezzi"],
  ["2A", "géographie", "Le golfe d'Ajaccio", "Le golfe d'Ajaccio ouvre largement la ville sur la mer et les montagnes environnantes. Ports, plages et îles Sanguinaires y dessinent un paysage très identifiable. En Corse-du-Sud, la capitale départementale garde un lien direct avec le relief et le large.", 2, "commune", "poétique", "Office de tourisme du Pays d'Ajaccio", "golfe-ajaccio"],
  ["2A", "gastronomie", "Le brocciu en Corse-du-Sud", "Le brocciu, fromage frais emblématique de Corse, entre dans des plats salés comme dans des desserts. En Corse-du-Sud, il accompagne fiadone, beignets ou recettes familiales. Sa texture légère et son goût lacté en font un marqueur culinaire très insulaire. Le recit gagne ainsi une accroche immediate.", 2, "commune", "neutre", "INAO", "brocciu-2a"],
  ["2A", "gastronomie", "Le figatellu d'hiver", "Le figatellu est une charcuterie corse souvent associée à l'hiver et aux repas au coin du feu. Il se grille, se partage et porte une forte dimension familiale. En Corse-du-Sud, la gastronomie garde ce lien direct avec l'élevage porcin et la saison.", 2, "commune", "neutre", "Office de tourisme de Corse", "figatellu-2a"],
  ["2A", "gastronomie", "Le fiadone au brocciu", "Le fiadone est un dessert corse à base de brocciu, d'œufs, de sucre et souvent de citron. Sa simplicité fait partie de son charme. En Corse-du-Sud, il incarne une pâtisserie familiale, moins spectaculaire qu'un gâteau de vitrine mais très attachée au terroir.", 2, "commune", "neutre", "Office de tourisme de Corse", "fiadone"],
  ["2A", "gastronomie", "La liqueur de myrte", "La myrte pousse dans le maquis corse et parfume des liqueurs servies en digestif. Son goût évoque directement les paysages secs et aromatiques de l'île. En Corse-du-Sud, cette boisson donne une traduction gourmande à la végétation du littoral et des collines.", 2, "commune", "poétique", "Office de tourisme de Corse", "myrte-2a"],
  ["2A", "gastronomie", "L'aziminu des côtes corses", "L'aziminu est une soupe de poissons corse, proche dans l'esprit de la bouillabaisse mais marquée par les produits locaux. En Corse-du-Sud, elle rappelle les ports, les rochers et la pêche côtière. Le plat met la mer dans l'assiette sans perdre l'accent insulaire.", 3, "peu commune", "neutre", "Office de tourisme de Corse", "aziminu"],
  ["2A", "culture", "La polyphonie corse", "La polyphonie corse occupe une place forte dans la culture de l'île. Les voix s'entrelacent dans des chants religieux ou profanes, souvent avec une intensité très dépouillée. En Corse-du-Sud, cette tradition sonore donne au territoire une présence culturelle immédiatement reconnaissable.", 2, "commune", "poétique", "Collectivité de Corse", "polyphonie-2a"],
  ["2A", "culture", "Ajaccio impériale", "Ajaccio entretient une relation culturelle forte avec Napoléon, entre musée, statues, noms de rues et mémoire familiale. Cette présence façonne une partie du récit touristique de la ville. En Corse-du-Sud, l'identité ajaccienne dialogue sans cesse avec l'héritage impérial. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "neutre", "Ville d'Ajaccio", "ajaccio-imperiale"],
  ["2A", "culture", "Sartène ville de caractère", "Sartène est souvent présentée comme une ville très corse, avec ses ruelles serrées, ses maisons sombres et ses traditions religieuses. Au-delà de la formule, le lieu possède une vraie densité culturelle. La Corse-du-Sud y montre une identité intérieure, grave et minérale.", 2, "commune", "poétique", "Office de tourisme de Sartène", "sartene-culture"],
  ["2A", "culture", "Les chants de confréries", "En Corse-du-Sud, les confréries religieuses participent encore à certaines fêtes et processions. Le chant, les vêtements et les parcours urbains donnent à ces moments une forte présence culturelle. Cette tradition relie les villages, les familles et la mémoire spirituelle de l'île.", 3, "peu commune", "neutre", "Collectivité de Corse", "confreries-2a"],
  ["2A", "culture", "Le maquis dans les récits", "Le maquis corse nourrit recits et chants : il nourrit récits, chants, histoires de résistance et imaginaires familiaux. En Corse-du-Sud, cette végétation dense devient un motif culturel. Elle évoque autant l'abri, la liberté que la difficulté de circuler. Cette precision donne un repere sensible.", 2, "commune", "poétique", "Parc naturel régional de Corse", "maquis-culture-2a"],
  ["2A", "insolite", "L'escalier du roi d'Aragon", "À Bonifacio, l'escalier du roi d'Aragon descend dans la falaise calcaire par des marches vertigineuses. La légende lui donne une origine spectaculaire, même si l'histoire est plus complexe. En Corse-du-Sud, le patrimoine se mélange facilement au récit et au vertige.", 2, "commune", "surprenant", "Office de tourisme de Bonifacio", "escalier-aragon"],
  ["2A", "insolite", "Les maisons au bord du vide", "À Bonifacio, certaines maisons semblent posées exactement sur le bord des falaises. Cette image frappe immédiatement les visiteurs. En Corse-du-Sud, l'insolite tient à cette manière de construire au contact du vide, entre protection, audace et spectacle naturel. Le recit reste court, mais plus incarne.", 2, "commune", "surprenant", "Office de tourisme de Bonifacio", "maisons-vide"],
  ["2A", "insolite", "Les rochers des Lavezzi", "Aux Lavezzi, les blocs de granite arrondis créent des formes presque sculptées. Selon la lumière, ils évoquent des animaux, des silhouettes ou des ruines imaginaires. En Corse-du-Sud, la géologie suffit parfois à produire un décor d'une étrangeté joyeuse. Cette mention ajoute une accroche memorable.", 2, "commune", "surprenant", "Réserve naturelle des Bouches de Bonifacio", "lavezzi-rochers"],
  ["2A", "insolite", "Les îles Sanguinaires au couchant", "Les îles Sanguinaires, à l'entrée du golfe d'Ajaccio, doivent beaucoup de leur réputation à la lumière du soir. Leur nom accentue encore cette impression dramatique. En Corse-du-Sud, un simple alignement d'îlots devient un symbole puissant du paysage ajaccien. Le point complete la scene sans l'alourdir.", 2, "commune", "poétique", "Office de tourisme du Pays d'Ajaccio", "sanguinaires"],
  ["2A", "insolite", "Un GR très corse", "Le GR20 traverse la Corse du nord au sud et passe par les montagnes de Corse-du-Sud. Il est réputé exigeant, avec des étapes minérales et des variations brutales de relief. L'insolite vient du contraste entre l'image balnéaire de l'île et cette aventure très physique.", 2, "commune", "surprenant", "Parc naturel régional de Corse", "gr20-2a"],
  ["2B", "histoire", "Bastia capitale génoise", "Bastia devient sous la domination génoise une place majeure du nord de la Corse. Son vieux port, sa citadelle et son quartier de Terra Nova gardent cette mémoire maritime. En Haute-Corse, l'histoire urbaine se lit encore dans la relation entre remparts, mer et pouvoir.", 2, "commune", "neutre", "Ville de Bastia", "bastia-genoise"],
  ["2B", "histoire", "Corte et Pascal Paoli", "Corte fut au XVIIIe siècle le cœur politique de la Corse de Pascal Paoli. La ville accueille une université et un musée qui prolongent cette mémoire. En Haute-Corse, Corte symbolise fortement l'intérieur de l'île, l'histoire nationale corse et l'idée d'autonomie.", 2, "commune", "neutre", "Musée de la Corse", "corte-paoli"],
  ["2B", "histoire", "Aléria antique", "Aléria conserve les traces d'une occupation antique importante sur la côte orientale. Le site rappelle les échanges entre Corse, Méditerranée et mondes étrusque puis romain. En Haute-Corse, l'histoire ne commence pas avec Gênes : elle plonge dans un réseau maritime très ancien.", 3, "peu commune", "neutre", "Musée d'Aléria", "aleria-antique"],
  ["2B", "histoire", "Ponte Novu", "La bataille de Ponte Novu, en 1769, marque la défaite des troupes de Pascal Paoli face aux forces françaises. Le lieu reste chargé dans la mémoire corse. En Haute-Corse, un pont devient ainsi un repère historique sensible, lié à la fin d'une expérience politique.", 3, "peu commune", "pédagogique", "Collectivité de Corse", "ponte-novu"],
  ["2B", "histoire", "L'Île-Rousse de Paoli", "L'Île-Rousse est fondée par Pascal Paoli pour concurrencer les ports dominés par Gênes. Son nom vient des îlots rouges qui bordent la ville. En Haute-Corse, l'urbanisme côtier porte donc une intention politique autant qu'un attrait paysager. Cette nuance donne plus d'epaisseur au lieu.", 3, "peu commune", "surprenant", "Office de tourisme de L'Île-Rousse Balagne", "ile-rousse-paoli"],
  ["2B", "histoire", "Mariana et les premiers évêques", "Près de Lucciana, le site de Mariana rappelle une cité antique et paléochrétienne importante. Cathédrale, vestiges et fouilles racontent un ancien centre religieux. En Haute-Corse, cette mémoire donne de la profondeur à la plaine orientale, souvent moins connue que les montagnes.", 3, "peu commune", "neutre", "Site archéologique de Mariana", "mariana"],
  ["2B", "histoire", "Les tours du Cap Corse", "Le Cap Corse conserve de nombreuses tours littorales héritées de la défense génoise. Elles surveillaient les approches maritimes et prévenaient les villages des dangers. En Haute-Corse, ces tours ponctuent le rivage comme des sentinelles de pierre. Ce point eclaire mieux son identite locale.", 2, "commune", "neutre", "Collectivité de Corse", "tours-cap-corse"],
  ["2B", "histoire", "Calvi et sa citadelle", "La citadelle de Calvi domine la baie et rappelle l'importance stratégique de la Balagne. Le site a longtemps regardé vers Gênes et la Méditerranée. En Haute-Corse, Calvi mêle histoire militaire, port de commerce et image balnéaire très forte. La scene devient plus facile a situer.", 2, "commune", "neutre", "Office de tourisme de Calvi Balagne", "calvi-citadelle"],
  ["2B", "histoire", "L'université de Corte renaît", "L'université de Corse rouvre à Corte en 1981, renouant avec une institution créée au XVIIIe siècle sous Pascal Paoli. Cette renaissance donne à la ville un rôle intellectuel central. En Haute-Corse, l'enseignement supérieur participe directement à l'identité territoriale. L'image reste simple, mais tres parlante.", 3, "peu commune", "pédagogique", "Université de Corse Pasquale Paoli", "universite-corte"],
  ["2B", "histoire", "Bastia pendant la Libération", "En 1943, Bastia connaît des combats lors de la libération de la Corse. La ville portuaire occupe une position importante dans la reprise de l'île. En Haute-Corse, cette mémoire rappelle que la Seconde Guerre mondiale s'est aussi jouée dans les ports méditerranéens.", 3, "peu commune", "neutre", "Musée de la Résistance corse", "bastia-liberation"],
  ["2B", "géographie", "Le doigt du Cap Corse", "Le Cap Corse forme une longue presqu'île pointée vers le nord, souvent comparée à un doigt. Crêtes, marines et villages perchés y composent un paysage très découpé. En Haute-Corse, cette géographie donne au département une silhouette immédiatement identifiable. Cette note renforce son ancrage culturel.", 2, "commune", "surprenant", "Office de tourisme du Cap Corse", "cap-corse"],
  ["2B", "géographie", "La Castagniccia", "La Castagniccia est un territoire de moyenne montagne marqué par les châtaigneraies, les villages et les pentes humides. Son nom dit l'importance du châtaignier dans l'économie ancienne. En Haute-Corse, cette région intérieure offre un contraste fort avec les plages de Balagne.", 2, "commune", "neutre", "Parc naturel régional de Corse", "castagniccia"],
  ["2B", "géographie", "La vallée de la Restonica", "La Restonica, près de Corte, attire par ses gorges, ses vasques et ses chemins vers les lacs d'altitude. Le site montre une Corse montagneuse, fraîche et minérale. En Haute-Corse, la randonnée révèle un visage très éloigné des cartes postales littorales.", 2, "commune", "poétique", "Office de tourisme de Corte", "restonica"],
  ["2B", "géographie", "Le désert des Agriates", "Le désert des Agriates n'est pas un désert de sable, mais un territoire de maquis, de crêtes et de plages difficiles d'accès. Son nom entretient une part de mystère. En Haute-Corse, cette zone protège un littoral sauvage très recherché. Le detail fait mieux sentir le terrain.", 2, "commune", "surprenant", "Conservatoire du littoral", "agriates"],
  ["2B", "géographie", "L'étang de Biguglia", "L'étang de Biguglia, au sud de Bastia, est la plus grande lagune de Corse. Il abrite oiseaux, poissons et milieux humides fragiles. En Haute-Corse, cette présence rappelle que les grands paysages passent aussi par les lagunes et les zones humides.", 2, "commune", "neutre", "Réserve naturelle de l'étang de Biguglia", "biguglia"],
  ["2B", "gastronomie", "La farine de châtaigne", "La farine de châtaigne corse, protégée par une appellation, occupe une place forte en Castagniccia. Elle sert à préparer pains, gâteaux ou pulenda. En Haute-Corse, la gastronomie raconte directement une forêt nourricière qui a longtemps soutenu les villages de montagne.", 2, "commune", "neutre", "INAO", "farine-chataigne"],
  ["2B", "gastronomie", "Le brocciu côté montagne", "Le brocciu est fabriqué à partir de lactosérum de brebis ou de chèvre et reste un ingrédient majeur de la cuisine corse. En Haute-Corse, il circule entre recettes salées, desserts et repas familiaux. Sa simplicité porte une forte identité insulaire.", 2, "commune", "neutre", "INAO", "brocciu-2b"],
  ["2B", "gastronomie", "Les canistrelli", "Les canistrelli sont de petits biscuits secs corses, souvent parfumés au vin blanc, au citron ou à l'anis. Faciles à transporter, ils accompagnent cafés, goûters et retours de randonnée. En Haute-Corse, cette gourmandise modeste a le goût du quotidien insulaire.", 2, "commune", "amusant", "Office de tourisme de Corse", "canistrelli"],
  ["2B", "gastronomie", "Le muscat du Cap Corse", "Le Muscat du Cap Corse bénéficie d'une appellation reconnue. Ce vin doux naturel accompagne volontiers desserts, fromages ou moments de fête. En Haute-Corse, il traduit en bouche la lumière sèche du Cap et les terrasses tournées vers la mer. Le point complete la scene sans l'alourdir.", 2, "commune", "poétique", "INAO", "muscat-cap-corse"],
  ["2B", "gastronomie", "La charcuterie de montagne", "La charcuterie corse s'appuie sur l'élevage porcin, les savoir-faire familiaux et l'affinage en montagne. En Haute-Corse, coppa, lonzu ou prisuttu racontent un lien ancien entre villages, châtaigneraies et saison froide. La gastronomie y reste fortement liée au relief. L'ensemble devient plus vivant et situe.", 2, "commune", "neutre", "Office de tourisme de Corse", "charcuterie-2b"],
  ["2B", "culture", "Le Museu di a Corsica", "À Corte, le Museu di a Corsica explore l'histoire, les pratiques et les représentations de l'île. Installé dans la citadelle, il donne une profondeur culturelle au centre montagneux. En Haute-Corse, le musée relie mémoire politique, vie quotidienne et identité contemporaine.", 2, "commune", "neutre", "Musée de la Corse", "museu-corsica"],
  ["2B", "culture", "La polyphonie de Balagne", "La Balagne est l'un des territoires associés au chant polyphonique corse. Les voix y portent autant la tradition religieuse que les créations contemporaines. En Haute-Corse, la culture se reconnaît souvent à cette densité sonore, sobre et très expressive. Cette precision ancre mieux le recit territorial.", 2, "commune", "poétique", "Collectivité de Corse", "polyphonie-2b"],
  ["2B", "culture", "Calvi sur scène", "Calvi accueille depuis longtemps des événements musicaux qui donnent à la ville une image festive et internationale. Le contraste entre citadelle ancienne et musiques actuelles est fort. En Haute-Corse, la culture balnéaire sait aussi devenir scène et rendez-vous estival. Le contexte rend le paysage plus lisible.", 2, "commune", "neutre", "Ville de Calvi", "calvi-musique"],
  ["2B", "culture", "Le théâtre de Bastia", "Le théâtre municipal de Bastia, inauguré au XIXe siècle, rappelle l'ambition culturelle d'une ville portuaire ouverte sur l'Italie. Sa présence donne au centre ancien une dimension de scène. En Haute-Corse, Bastia porte une tradition urbaine et artistique souvent sous-estimée. Le fait ajoute une memoire locale precise.", 3, "peu commune", "neutre", "Ville de Bastia", "theatre-bastia"],
  ["2B", "culture", "La langue corse à Corte", "Corte occupe une place importante dans la transmission universitaire et culturelle de la langue corse. Enseignement, recherche et vie étudiante y donnent une présence actuelle à cette langue. En Haute-Corse, la culture ne se limite pas au patrimoine : elle se pratique au présent.", 2, "commune", "pédagogique", "Université de Corse Pasquale Paoli", "langue-corse-corte"],
  ["2B", "insolite", "Un désert sans sable", "Le désert des Agriates surprend par son nom. On y trouve surtout maquis, pistes, criques et plages, pas des dunes sahariennes. En Haute-Corse, cette appellation crée un décalage savoureux entre imaginaire aride et réalité méditerranéenne très vivante. Le recit gagne ainsi une accroche immediate.", 2, "commune", "surprenant", "Conservatoire du littoral", "agriates-insolite"],
  ["2B", "insolite", "Calvi et Colomb", "Une tradition locale affirme que Christophe Colomb serait né à Calvi, même si cette attribution reste discutée. La ville entretient ce récit avec prudence et humour. En Haute-Corse, certaines histoires valent autant par leur pouvoir d'imaginaire que par leur certitude.", 3, "rare", "piégeux", "Ville de Calvi", "colomb-calvi"],
  ["2B", "insolite", "Des villages en balcon", "Dans le Cap Corse et la Balagne, plusieurs villages semblent accrochés aux pentes, entre mer et montagne. Cette disposition crée des vues spectaculaires mais raconte aussi une logique ancienne de protection. En Haute-Corse, l'insolite naît souvent de cette verticalité habitée.", 2, "commune", "poétique", "Office de tourisme du Cap Corse", "villages-balcon"],
  ["2B", "insolite", "Biguglia aux portes de Bastia", "L'étang de Biguglia offre un paysage de lagune presque immédiat au sud de l'agglomération bastiaise. Le contraste entre ville, route, oiseaux et eau calme est saisissant. En Haute-Corse, un espace naturel majeur se trouve tout près du quotidien urbain. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "Réserve naturelle de l'étang de Biguglia", "biguglia-insolite"],
  ["2B", "insolite", "Le train des montagnes", "Le chemin de fer corse relie Bastia, Corte, Ajaccio et Calvi en franchissant des reliefs exigeants. Ponts, tunnels et petites gares donnent au voyage un caractère très particulier. En Haute-Corse, prendre le train devient presque une lecture lente du paysage.", 2, "commune", "surprenant", "Chemins de fer de la Corse", "train-corse"],
  ["971", "histoire", "Louis Delgrès au Matouba", "En 1802, Louis Delgrès choisit la résistance face au rétablissement de l'esclavage voulu par Bonaparte. Son geste au Matouba reste un moment majeur de la mémoire guadeloupéenne. En Guadeloupe, cette histoire donne une force particulière aux lieux liés à la liberté.", 3, "peu commune", "neutre", "Mémorial ACTe", "delgres-matouba"],
  ["971", "histoire", "Le fort Delgrès", "Le fort Delgrès, à Basse-Terre, domine la mer et porte une mémoire militaire et politique très forte. Son nom honore Louis Delgrès, figure de résistance à l'esclavage. En Guadeloupe, les fortifications racontent autant la défense coloniale que les combats pour la dignité.", 2, "commune", "neutre", "Fort Delgrès", "fort-delgres"],
  ["971", "histoire", "L'abolition de 1848", "L'abolition de l'esclavage en 1848 transforme profondément la société guadeloupéenne. Le souvenir de cette rupture reste central dans la mémoire du territoire. En Guadeloupe, l'histoire ne se comprend pas sans cette lutte longue, douloureuse et toujours présente dans les commémorations.", 2, "commune", "pédagogique", "Mémorial ACTe", "abolition-1848-guadeloupe"],
  ["971", "histoire", "Le Mémorial ACTe", "Le Mémorial ACTe, à Pointe-à-Pitre, est consacré à l'histoire de l'esclavage et de la traite. Son architecture contemporaine contraste avec la gravité du sujet. En Guadeloupe, ce lieu inscrit la mémoire dans un équipement culturel majeur, visible au bord de la mer.", 2, "commune", "neutre", "Mémorial ACTe", "memorial-acte"],
  ["971", "histoire", "Pointe-à-Pitre commerçante", "Pointe-à-Pitre s'est développée comme un port et une ville de commerce au cœur de l'archipel. Marchés, quais et entrepôts ont longtemps structuré son activité. En Guadeloupe, cette ville raconte la circulation des marchandises, des personnes et des cultures caribéennes. Cette precision donne un repere sensible.", 2, "commune", "neutre", "Ville de Pointe-à-Pitre", "pointe-commerce"],
  ["971", "histoire", "Basse-Terre ancienne capitale", "Basse-Terre conserve un rôle historique important, avec son fort, ses rues anciennes et sa proximité avec la Soufrière. La ville rappelle le poids de la côte sous le vent dans la construction de la Guadeloupe. Son histoire mêle administration, défense et relief volcanique.", 2, "commune", "neutre", "Ville de Basse-Terre", "basse-terre-histoire"],
  ["971", "histoire", "La bataille des Saintes", "En 1782, la bataille des Saintes oppose flottes française et britannique dans les eaux proches de l'archipel. Cet épisode naval rappelle la place stratégique de la Guadeloupe dans les rivalités impériales. La mer des Caraïbes fut aussi un théâtre militaire européen.", 3, "peu commune", "neutre", "Musée national de la Marine", "bataille-saintes"],
  ["971", "histoire", "La Soufrière évacuée", "En 1976, la menace d'éruption de la Soufrière entraîne l'évacuation d'une partie importante de la Basse-Terre. L'événement marque durablement la mémoire locale. En Guadeloupe, le volcan pese aussi sur les decisions publiques et la securite collective. Cette mention ajoute une accroche memorable.", 3, "peu commune", "surprenant", "Observatoire volcanologique et sismologique de Guadeloupe", "soufriere-1976"],
  ["971", "histoire", "Marie-Galante sucrière", "Marie-Galante garde une forte mémoire liée à la canne à sucre, aux habitations et aux moulins. Cette île de l'archipel guadeloupéen raconte une économie ancienne, dure et structurante. Son paysage actuel conserve encore les traces de cette histoire agricole et industrielle.", 2, "commune", "neutre", "Office de tourisme de Marie-Galante", "marie-galante-sucre"],
  ["971", "histoire", "Les traces amérindiennes", "Avant la colonisation européenne, la Guadeloupe est habitée par des populations amérindiennes. Des sites archéologiques, des pétroglyphes et des objets rappellent cette présence ancienne. L'histoire guadeloupéenne dépasse donc largement la période coloniale et s'inscrit dans une longue histoire caribéenne. L'ensemble devient plus vivant et situe.", 3, "peu commune", "pédagogique", "Musée Edgar Clerc", "amerindiens-guadeloupe"],
  ["971", "géographie", "L'archipel papillon", "La Guadeloupe est souvent décrite comme un papillon vu du ciel, avec Basse-Terre et Grande-Terre formant deux ailes. Cette image simple dit bien la diversité du territoire. Montagne volcanique, plateaux calcaires, îles proches et lagons composent un archipel très contrasté.", 1, "commune", "surprenant", "Comité du tourisme des îles de Guadeloupe", "papillon-guadeloupe"],
  ["971", "géographie", "La Soufrière active", "La Soufrière domine Basse-Terre et reste un volcan actif surveillé de près. Ses fumerolles, ses sentiers humides et ses nuages fréquents donnent un paysage très particulier. En Guadeloupe, la montagne volcanique impose sa présence au-dessus de la forêt tropicale. Cette precision ancre mieux le recit territorial.", 2, "commune", "neutre", "Observatoire volcanologique et sismologique de Guadeloupe", "soufriere-volcan"],
  ["971", "géographie", "Grande-Terre calcaire", "Grande-Terre présente des paysages plus secs et calcaires que Basse-Terre. Plaines, falaises, plages et champs de canne y composent une autre Guadeloupe. Cette différence géologique explique une partie des contrastes entre les deux grandes parties de l'archipel. Le contexte rend le paysage plus lisible.", 2, "commune", "pédagogique", "Parc national de la Guadeloupe", "grande-terre-calcaire"],
  ["971", "géographie", "Le Grand Cul-de-Sac Marin", "Le Grand Cul-de-Sac Marin protège mangroves, herbiers et récifs entre Basse-Terre et Grande-Terre. Cet espace forme un vaste paysage d'eau peu profonde. En Guadeloupe, la géographie littorale se joue autant dans les mangroves que sur les plages. Le fait ajoute une memoire locale precise.", 2, "commune", "neutre", "Parc national de la Guadeloupe", "grand-cul-de-sac"],
  ["971", "géographie", "Les Saintes en relief", "Les Saintes forment un petit archipel au sud de la Guadeloupe, avec des mornes, des anses et une baie célèbre. Leur relief crée des vues très découpées. Dans l'ensemble guadeloupéen, ces îles donnent une impression de miniature maritime très lisible.", 2, "commune", "poétique", "Comité du tourisme des îles de Guadeloupe", "saintes-geographie"],
  ["971", "gastronomie", "Le bokit", "Le bokit est un pain frit garni, devenu une spécialité populaire de Guadeloupe. On le trouve souvent dans la rue, avec morue, poulet, crudités ou sauces. Sa gourmandise simple raconte une cuisine mobile, généreuse et très attachée aux habitudes quotidiennes.", 2, "commune", "amusant", "Comité du tourisme des îles de Guadeloupe", "bokit"],
  ["971", "gastronomie", "Le colombo guadeloupéen", "Le colombo, plat épicé d'inspiration indienne et antillaise, fait partie des grands classiques guadeloupéens. Poulet, cabri ou poisson s'y parfument d'un mélange d'épices très reconnaissable. En Guadeloupe, la cuisine raconte les circulations humaines autant que les produits locaux. Ce point eclaire mieux son identite locale.", 2, "commune", "neutre", "Comité du tourisme des îles de Guadeloupe", "colombo-guadeloupe"],
  ["971", "gastronomie", "Les accras de morue", "Les accras de morue sont de petits beignets salés, souvent servis en entrée ou à l'apéritif. Leur texture croustillante et leur parfum pimenté en font une spécialité immédiatement festive. En Guadeloupe, ils accompagnent volontiers repas familiaux, marchés et tables créoles.", 2, "commune", "amusant", "Comité du tourisme des îles de Guadeloupe", "accras-guadeloupe"],
  ["971", "gastronomie", "Le tourment d'amour", "Le tourment d'amour est une petite tarte sucrée associée aux Saintes, souvent garnie de confiture de coco, goyave ou banane. Son nom intrigue autant que son goût. En Guadeloupe, cette pâtisserie insulaire garde une forte charge affective. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "Office de tourisme de Terre-de-Haut", "tourment-amour"],
  ["971", "gastronomie", "Le rhum de Marie-Galante", "Marie-Galante est réputée pour ses distilleries et ses rhums agricoles puissants. La canne à sucre y structure encore les paysages et les savoir-faire. Dans l'archipel guadeloupéen, le rhum raconte une histoire agricole, industrielle et festive à la fois. Le territoire y gagne une couleur nette.", 2, "commune", "neutre", "Office de tourisme de Marie-Galante", "rhum-marie-galante"],
  ["971", "culture", "Le gwoka reconnu", "Le gwoka, musique et danse liées aux tambours ka, est inscrit au patrimoine culturel immatériel de l'UNESCO. Il porte une mémoire de résistance, de fête et d'expression populaire. En Guadeloupe, la culture se ressent fortement dans le rythme et la participation collective.", 2, "commune", "neutre", "UNESCO", "gwoka"],
  ["971", "culture", "Le carnaval guadeloupéen", "Le carnaval de Guadeloupe anime plusieurs semaines de défilés, de musiques et de groupes costumés. Il mêle fête, satire, tradition et énergie de rue. Cette culture carnavalesque donne au territoire un calendrier vivant, très attendu et profondément partagé. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "amusant", "Comité du tourisme des îles de Guadeloupe", "carnaval-guadeloupe"],
  ["971", "culture", "Le créole guadeloupéen", "Le créole guadeloupéen porte une grande part de l'expression quotidienne, musicale et littéraire du territoire. Il raconte l'histoire des contacts, des résistances et des inventions de langage. En Guadeloupe, parler culture revient souvent à écouter les langues qui circulent. La reference garde une portee tres locale.", 2, "commune", "pédagogique", "Collectivité régionale de Guadeloupe", "creole-guadeloupe"],
  ["971", "culture", "La Route du Rhum", "La Route du Rhum relie Saint-Malo à Pointe-à-Pitre depuis 1978. Son arrivée en Guadeloupe transforme l'archipel en scène de grande course océanique. Ce rendez-vous donne au territoire une visibilité maritime très forte, entre sport, fête populaire et culture du large.", 2, "commune", "neutre", "Route du Rhum - Destination Guadeloupe", "route-du-rhum"],
  ["971", "culture", "Le musée Edgar Clerc", "Le musée Edgar Clerc, au Moule, présente des collections archéologiques liées aux populations amérindiennes de Guadeloupe. Il donne une profondeur culturelle à l'archipel avant l'arrivée européenne. Le lieu rappelle que la Caraïbe possède des mémoires très anciennes. Cette precision donne un repere sensible.", 3, "peu commune", "neutre", "Musée Edgar Clerc", "musee-edgar-clerc"],
  ["971", "insolite", "Un volcan sous surveillance", "La Soufrière est surveillée en permanence par un observatoire volcanologique. Cette présence scientifique donne une dimension particulière au quotidien guadeloupéen. L'insolite vient du voisinage entre sentiers touristiques, forêt tropicale et instruments attentifs aux mouvements du volcan. Le paysage prend alors une presence nette.", 2, "commune", "surprenant", "Observatoire volcanologique et sismologique de Guadeloupe", "soufriere-surveillance"],
  ["971", "insolite", "La réserve Cousteau", "Autour des îlets Pigeon, la réserve Cousteau attire plongeurs et amateurs de fonds marins. Le nom évoque Jacques-Yves Cousteau et la découverte sous-marine. En Guadeloupe, une partie du patrimoine se trouve sous l'eau, entre coraux, poissons et pédagogie environnementale. Le recit reste court, mais plus incarne.", 2, "commune", "surprenant", "Parc national de la Guadeloupe", "reserve-cousteau"],
  ["971", "insolite", "Le papillon vu du ciel", "La forme de la Guadeloupe frappe facilement sur une carte : deux grandes terres reliées comme les ailes d'un papillon. Cette image est devenue un raccourci affectif très populaire. L'insolite tient à cette géographie lisible d'un seul regard. Cette mention ajoute une accroche memorable.", 1, "commune", "surprenant", "Comité du tourisme des îles de Guadeloupe", "papillon-insolite"],
  ["971", "insolite", "Les moulins de Marie-Galante", "Marie-Galante est parfois surnommée l'île aux cent moulins, en raison des nombreux vestiges liés à la canne. Ces silhouettes racontent un passé sucrier intense. En Guadeloupe, l'insolite naît de cette accumulation de ruines agricoles dans un paysage encore très ouvert.", 2, "commune", "surprenant", "Office de tourisme de Marie-Galante", "moulins-marie-galante"],
  ["971", "insolite", "La baie des Saintes", "La baie des Saintes est régulièrement citée parmi les plus belles baies du monde dans les classements touristiques. Même sans mesurer ce titre, le site impressionne par son équilibre entre reliefs et eau calme. En Guadeloupe, la carte postale a parfois une vraie précision géographique.", 2, "commune", "surprenant", "Office de tourisme de Terre-de-Haut", "baie-saintes"],
  ["972", "histoire", "Saint-Pierre détruite en 1902", "En 1902, l'éruption de la montagne Pelée détruit Saint-Pierre et marque profondément l'histoire martiniquaise. La ville, alors très active, est brutalement anéantie. En Martinique, cette catastrophe reste un repère majeur, à la fois scientifique, humain et mémoriel. Le detail donne au lieu une presence plus concrete.", 2, "commune", "neutre", "Observatoire volcanologique et sismologique de Martinique", "saint-pierre-1902"],
  ["972", "histoire", "La montagne Pelée", "La montagne Pelée domine le nord de la Martinique et reste liée à l'une des éruptions les plus meurtrières du XXe siècle. Son histoire a influencé la volcanologie mondiale. Le volcan incarne à la fois la beauté, le danger et la mémoire du territoire.", 2, "commune", "pédagogique", "Observatoire volcanologique et sismologique de Martinique", "pelee-histoire"],
  ["972", "histoire", "Aimé Césaire à Fort-de-France", "Aimé Césaire, poète, penseur de la négritude et maire de Fort-de-France pendant de longues années, occupe une place centrale dans la mémoire martiniquaise. Son œuvre relie littérature, politique et dignité. En Martinique, la culture a souvent porté une parole historique puissante.", 2, "commune", "neutre", "Fondation Aimé Césaire", "cesaire-fort-de-france"],
  ["972", "histoire", "Victor Schoelcher et l'abolition", "La commune de Schoelcher porte le nom de Victor Schoelcher, figure associée à l'abolition de l'esclavage en 1848. Cette mémoire reste discutée et replacée dans des luttes plus larges. En Martinique, l'abolition se comprend avec les résistances des personnes réduites en esclavage.", 3, "peu commune", "pédagogique", "Collectivité territoriale de Martinique", "schoelcher-abolition"],
  ["972", "histoire", "Le Rocher du Diamant navire", "Pendant les guerres napoléoniennes, les Britanniques occupent le Rocher du Diamant et le traitent comme un navire de guerre. L'épisode est étonnant par son audace militaire. En Martinique, un îlot volcanique devient ainsi un fragment d'histoire navale. Cette nuance donne plus d'epaisseur au lieu.", 3, "rare", "surprenant", "Musée national de la Marine", "diamant-hms"],
  ["972", "histoire", "Le fort Saint-Louis", "Le fort Saint-Louis protège Fort-de-France depuis l'époque coloniale et reste un site militaire. Il rappelle la place stratégique de la Martinique dans les Caraïbes. Entre baie, remparts et ville, ce fort donne à la capitale une profondeur historique très visible.", 2, "commune", "neutre", "Ville de Fort-de-France", "fort-saint-louis"],
  ["972", "histoire", "L'Anse Cafard", "Le mémorial de l'Anse Cafard, au Diamant, commémore un naufrage de navire négrier survenu au XIXe siècle. Ses statues tournées vers la mer créent une émotion forte. En Martinique, la mémoire de l'esclavage se lit aussi dans le paysage littoral.", 3, "peu commune", "neutre", "Ville du Diamant", "anse-cafard"],
  ["972", "histoire", "L'habitation Clément", "L'habitation Clément, au François, raconte l'histoire agricole, industrielle et sociale liée à la canne et au rhum. Le site associe maison créole, distillerie ancienne et parc. En Martinique, une habitation devient un lieu de mémoire complexe, entre patrimoine et économie.", 2, "commune", "neutre", "Fondation Clément", "habitation-clement"],
  ["972", "histoire", "Joséphine aux Trois-Îlets", "Joséphine de Beauharnais naît aux Trois-Îlets, dans une famille de planteurs. Sa mémoire reste sensible, liée à l'histoire impériale et à l'esclavage. En Martinique, ce personnage illustre la nécessité de lire les figures célèbres avec contexte et prudence. L'image reste simple, mais tres parlante.", 3, "peu commune", "piégeux", "La Savane des Esclaves", "josephine-trois-ilets"],
  ["972", "histoire", "L'abolition en Martinique", "L'esclavage est aboli en Martinique en 1848, dans un contexte de mobilisations et de tensions locales. La date du 22 mai occupe une place forte dans la mémoire martiniquaise. Elle rappelle que la liberté fut aussi arrachée par l'action des personnes concernées.", 2, "commune", "pédagogique", "Collectivité territoriale de Martinique", "abolition-1848-martinique"],
  ["972", "géographie", "La Pelée au nord", "La montagne Pelée domine le nord de la Martinique avec ses pentes humides, ses nuages et ses sentiers. Elle donne au territoire une verticalité puissante. La géographie martiniquaise se lit dans ce contraste entre volcan, forêts, bourgs littoraux et plantations anciennes.", 2, "commune", "poétique", "Parc naturel régional de Martinique", "pelee-geographie"],
  ["972", "géographie", "La presqu'île de la Caravelle", "La presqu'île de la Caravelle avance dans l'Atlantique avec mangroves, falaises, savanes sèches et ruines d'habitation. Elle condense plusieurs paysages martiniquais en peu d'espace. Cette diversité en fait un site clé pour comprendre le littoral au vent. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "neutre", "Parc naturel régional de Martinique", "caravelle"],
  ["972", "géographie", "La mangrove de Génipa", "La baie de Génipa, près de Fort-de-France, abrite une mangrove importante pour la biodiversité et la protection du littoral. Racines, vasières et oiseaux y composent un paysage fragile. En Martinique, la géographie tropicale se joue aussi dans ces zones humides discrètes.", 2, "commune", "neutre", "Parc naturel marin de Martinique", "genipa"],
  ["972", "géographie", "Le Rocher du Diamant", "Le Rocher du Diamant se dresse au large du sud de la Martinique comme une silhouette isolée. Sa forme attire le regard depuis la côte. Ce relief volcanique donne au paysage marin un repère net, à la fois naturel, historique et presque théâtral.", 2, "commune", "poétique", "Office de tourisme de Martinique", "rocher-diamant"],
  ["972", "géographie", "Plages noires et plages claires", "La Martinique alterne plages de sable noir au nord volcanique et plages plus claires au sud. Cette différence visible raconte la géologie de l'île. En quelques kilomètres, le littoral passe d'une ambiance minérale sombre à des lagons très lumineux. Cette precision donne un repere sensible.", 2, "commune", "surprenant", "Office de tourisme de Martinique", "plages-noires-claires"],
  ["972", "gastronomie", "Le rhum agricole AOC", "La Martinique possède une appellation d'origine contrôlée pour son rhum agricole, produit à partir du jus de canne. Cette reconnaissance souligne l'importance du terroir, des distilleries et des savoir-faire. Dans l'île, le rhum est autant une économie qu'une culture. Le paysage prend alors une presence nette.", 2, "commune", "neutre", "INAO", "rhum-aoc-martinique"],
  ["972", "gastronomie", "Les accras martiniquais", "Les accras de morue font partie des entrées les plus familières de la cuisine martiniquaise. Leur pâte légère, leur parfum d'herbes et leur pointe de piment ouvrent souvent le repas. En Martinique, cette bouchée simple concentre convivialité et goût créole.", 2, "commune", "amusant", "Office de tourisme de Martinique", "accras-martinique"],
  ["972", "gastronomie", "Le colombo de Martinique", "Le colombo associe viandes ou poissons à un mélange d'épices arrivé par les circulations indo-caribéennes. En Martinique, il fait partie des plats familiaux qui racontent une histoire de rencontres. Son parfum suffit souvent à installer une table créole. Cette mention ajoute une accroche memorable.", 2, "commune", "neutre", "Office de tourisme de Martinique", "colombo-martinique"],
  ["972", "gastronomie", "Le ti-punch", "Le ti-punch martiniquais réunit rhum agricole, citron vert et sucre de canne. Sa préparation paraît simple, mais chacun a ses habitudes. En Martinique, ce petit verre raconte autant la canne, les distilleries que l'art de recevoir sans cérémonie inutile. Le point complete la scene sans l'alourdir.", 2, "commune", "amusant", "Office de tourisme de Martinique", "ti-punch"],
  ["972", "gastronomie", "Le blaff de poisson", "Le blaff est une préparation de poisson mariné puis cuit dans un bouillon parfumé au citron, aux herbes et au piment. En Martinique, il garde un lien direct avec la mer et les repas familiaux. Le plat privilégie la fraîcheur plutôt que la démonstration.", 3, "peu commune", "neutre", "Office de tourisme de Martinique", "blaff"],
  ["972", "culture", "Le bèlè", "Le bèlè associe chant, tambour, danse et réponse collective. Cette tradition martiniquaise porte une mémoire populaire forte, liée aux campagnes et aux résistances culturelles. En Martinique, le corps, la voix et le rythme deviennent des archives vivantes. Le detail donne au lieu une presence plus concrete.", 2, "commune", "poétique", "Collectivité territoriale de Martinique", "bele"],
  ["972", "culture", "La yole ronde", "La yole ronde de Martinique est inscrite au patrimoine culturel immatériel de l'UNESCO. Ces embarcations sans quille demandent un équilibre spectaculaire et un fort esprit d'équipage. La course de yoles transforme la mer en scène sportive et culturelle. Cette precision ancre mieux le recit territorial.", 2, "commune", "surprenant", "UNESCO", "yole-ronde"],
  ["972", "culture", "Césaire et la négritude", "L'œuvre d'Aimé Césaire a contribué à formuler la négritude, mouvement littéraire et politique majeur du XXe siècle. Depuis la Martinique, sa parole a circulé bien au-delà de l'île. Cette puissance littéraire donne au territoire une portée intellectuelle internationale. Le contexte rend le paysage plus lisible.", 2, "commune", "neutre", "Fondation Aimé Césaire", "cesaire-negritude"],
  ["972", "culture", "Le carnaval de Martinique", "Le carnaval martiniquais mêle costumes, musique, satire et personnages populaires comme Vaval. Plusieurs jours de défilés transforment les rues en scène collective. En Martinique, cette fête concentre humour, critique sociale, rythme et invention visuelle. Le fait ajoute une memoire locale precise.", 2, "commune", "amusant", "Office de tourisme de Martinique", "carnaval-martinique"],
  ["972", "culture", "La langue créole martiniquaise", "Le créole martiniquais occupe une place essentielle dans la parole quotidienne, la musique, le théâtre et la littérature. Il porte des nuances, des images et une mémoire propres. En Martinique, la culture se comprend fortement par les langues que les habitants font vivre.", 2, "commune", "pédagogique", "Collectivité territoriale de Martinique", "creole-martinique"],
  ["972", "insolite", "Le rocher devenu navire", "Le Rocher du Diamant a été administré par les Britanniques comme un navire de guerre, avec équipage et commandement. L'idée paraît invraisemblable, mais elle appartient bien à l'histoire militaire. En Martinique, un caillou en mer peut devenir un bâtiment naval.", 3, "rare", "surprenant", "Musée national de la Marine", "diamant-insolite"],
  ["972", "insolite", "Saint-Pierre Pompéi des Caraïbes", "Saint-Pierre est parfois surnommée la Pompéi des Caraïbes après la catastrophe de 1902. L'expression frappe par sa force, même si chaque drame garde son contexte propre. En Martinique, les ruines et le volcan entretiennent une mémoire très particulière. Ce point eclaire mieux son identite locale.", 2, "commune", "surprenant", "Ville de Saint-Pierre", "pompei-caraibes"],
  ["972", "insolite", "Les yoles sans quille", "Les yoles rondes martiniquaises naviguent sans quille, ce qui oblige l'équipage à compenser l'équilibre avec des bois dressés sur les côtés. Le spectacle est impressionnant. En Martinique, la maîtrise technique se voit immédiatement dans la posture des équipiers. La scene devient plus facile a situer.", 2, "commune", "surprenant", "Fédération des yoles rondes de Martinique", "yoles-sans-quille"],
  ["972", "insolite", "Une AOC sous les tropiques", "Le rhum agricole de Martinique bénéficie d'une AOC, distinction plus souvent associée aux vins ou aux fromages métropolitains. Cette reconnaissance surprend parfois les visiteurs. Elle rappelle que le terroir tropical peut être décrit avec une précision très exigeante. L'image reste simple, mais tres parlante.", 2, "commune", "surprenant", "INAO", "aoc-tropicale"],
  ["972", "insolite", "La bibliothèque Schoelcher", "La bibliothèque Schoelcher, à Fort-de-France, présente une architecture métallique et colorée venue de la fin du XIXe siècle. Elle fut d'abord montrée à Paris avant d'être installée en Martinique. Le bâtiment donne au centre-ville une silhouette culturelle immédiatement reconnaissable. Le territoire y gagne une couleur nette.", 2, "commune", "surprenant", "Bibliothèque Schoelcher", "bibliotheque-schoelcher"],
  ["973", "histoire", "Le bagne de Saint-Laurent", "Saint-Laurent-du-Maroni fut l'un des grands centres du bagne de Guyane. Les bâtiments conservés rappellent l'arrivée, le tri et la vie des condamnés. En Guyane, cette histoire pénitentiaire pèse encore fortement sur les lieux et sur l'imaginaire national. Cette note renforce son ancrage culturel.", 2, "commune", "neutre", "Camp de la Transportation", "bagne-saint-laurent"],
  ["973", "histoire", "Les îles du Salut", "Les îles du Salut, au large de Kourou, sont associées au bagne et à l'enfermement de prisonniers célèbres ou anonymes. Leur beauté tropicale contraste avec la dureté de cette histoire. En Guyane, certains paysages portent une mémoire très sombre. Le lieu devient moins abstrait pour le joueur.", 2, "commune", "neutre", "Centre des monuments nationaux", "iles-du-salut"],
  ["973", "histoire", "Dreyfus à l'île du Diable", "Alfred Dreyfus fut détenu à l'île du Diable, dans l'archipel des îles du Salut, après sa condamnation injuste. L'affaire a marqué durablement l'histoire politique française. En Guyane, ce lieu isolé reste lié à une injustice devenue symbole national. La reference garde une portee tres locale.", 2, "commune", "neutre", "Centre des monuments nationaux", "dreyfus-diable"],
  ["973", "histoire", "Kourou et l'espace", "Le Centre spatial guyanais s'installe à Kourou dans les années 1960. Sa position proche de l'équateur favorise les lancements. En Guyane, l'histoire contemporaine prend une dimension spatiale rare, entre technologie européenne, territoire amazonien et enjeux géopolitiques. Le detail fait mieux sentir le terrain.", 2, "commune", "surprenant", "Centre spatial guyanais", "kourou-espace"],
  ["973", "histoire", "Cayenne capitale administrative", "Cayenne concentre depuis longtemps les fonctions administratives de la Guyane. Son centre ancien, ses places et ses maisons créoles racontent une histoire urbaine caribéenne et amazonienne. La ville donne au territoire un visage politique, portuaire et culturel très dense. Cette precision donne un repere sensible.", 2, "commune", "neutre", "Ville de Cayenne", "cayenne-histoire"],
  ["973", "histoire", "Félix Éboué", "Félix Éboué, né à Cayenne, devient une grande figure de la France libre pendant la Seconde Guerre mondiale. Son parcours dépasse largement la Guyane. Pour le territoire, il représente une personnalité historique majeure, liée à la République, à l'empire colonial et à la Résistance.", 2, "commune", "neutre", "Musée Alexandre-Franconie", "felix-eboue"],
  ["973", "histoire", "Les mémoires amérindiennes", "La Guyane est habitée par plusieurs peuples autochtones, dont les histoires précèdent largement la colonisation européenne. Langues, savoirs, territoires et cultures restent essentiels pour comprendre le département. Cette profondeur historique rappelle que la Guyane ne se résume pas à Cayenne ou Kourou.", 3, "peu commune", "pédagogique", "Parc amazonien de Guyane", "memoires-amerindiennes"],
  ["973", "histoire", "Les sociétés bushinenguées", "Les peuples bushinengués, descendants de personnes mises en esclavage ayant fui les plantations, ont construit des sociétés originales le long des fleuves. Leur histoire est liée à la résistance, aux mobilités et aux échanges. En Guyane, le Maroni porte une mémoire politique et culturelle forte.", 3, "peu commune", "neutre", "Parc amazonien de Guyane", "bushinengue"],
  ["973", "histoire", "Le territoire de l'Inini", "De 1930 à 1946, l'intérieur de la Guyane est administré séparément sous le nom de territoire de l'Inini. Cette organisation reflète la difficulté à gouverner un espace immense et forestier. En Guyane, l'histoire administrative révèle l'ampleur du territoire. Le point complete la scene sans l'alourdir.", 4, "rare", "pédagogique", "Archives territoriales de Guyane", "inini"],
  ["973", "histoire", "L'abolition en Guyane", "L'esclavage est aboli en Guyane en 1848, comme dans les autres colonies françaises. Cette rupture transforme les sociétés, le travail et les rapports de pouvoir. En Guyane, la mémoire de l'abolition croise les histoires créoles, amérindiennes, bushinenguées et migratoires. L'ensemble devient plus vivant et situe.", 3, "peu commune", "pédagogique", "Collectivité territoriale de Guyane", "abolition-guyane"],
  ["973", "géographie", "La forêt amazonienne française", "La Guyane est couverte en grande partie par la forêt amazonienne. Cette réalité en fait un département français très différent par ses distances, ses milieux et sa biodiversité. Ici, la géographie impose une autre échelle que celle de la métropole.", 1, "commune", "surprenant", "Parc amazonien de Guyane", "foret-amazonienne"],
  ["973", "géographie", "Le fleuve Maroni", "Le Maroni marque la frontière avec le Suriname et sert de grand axe de circulation pour de nombreuses communes. Pirogues, villages et échanges s'organisent autour de lui. En Guyane, le fleuve joue parfois le rôle qu'une route tiendrait ailleurs. Cette precision ancre mieux le recit territorial.", 2, "commune", "neutre", "Collectivité territoriale de Guyane", "maroni"],
  ["973", "géographie", "L'Oyapock frontière", "L'Oyapock sépare la Guyane du Brésil et donne son nom au pont qui relie les deux rives. Ce fleuve inscrit le département dans une géographie sud-américaine très concrète. La frontière y est à la fois naturelle, politique et quotidienne. Le contexte rend le paysage plus lisible.", 2, "commune", "neutre", "Collectivité territoriale de Guyane", "oyapock"],
  ["973", "géographie", "Les marais de Kaw", "Les marais de Kaw forment l'une des grandes zones humides de Guyane, avec savanes inondées, oiseaux et caïmans. Ce paysage rappelle que l'Amazonie française n'est pas uniquement forestière. L'eau, la vase et les herbiers y dessinent un monde très particulier.", 2, "commune", "neutre", "Réserve naturelle nationale des marais de Kaw-Roura", "kaw"],
  ["973", "géographie", "Une façade sur l'Atlantique", "La Guyane possède une longue façade atlantique, souvent marquée par les mangroves, les vases et les mouvements de sédiments venus de l'Amazone. Ce littoral changeant contraste avec l'image de plages fixes. En Guyane, la côte est un paysage mobile. Cette nuance donne plus d'epaisseur au lieu.", 2, "commune", "pédagogique", "Ifremer Guyane", "littoral-guyane"],
  ["973", "gastronomie", "Le bouillon d'awara", "Le bouillon d'awara est un plat emblématique de Guyane, souvent associé aux fêtes de Pâques. Il demande de nombreux ingrédients et une préparation longue. Ce plat rassemble viandes, poissons, légumes et pâte d'awara dans une cuisine de patience et de partage.", 2, "commune", "neutre", "Comité du tourisme de Guyane", "bouillon-awara"],
  ["973", "gastronomie", "Le couac de manioc", "Le couac, semoule de manioc torréfiée, accompagne de nombreux repas en Guyane. Il se conserve bien et porte une histoire alimentaire liée aux savoirs amérindiens. Dans ce territoire forestier et fluvial, le manioc reste une base discrète mais essentielle. Ce point eclaire mieux son identite locale.", 2, "commune", "neutre", "Parc amazonien de Guyane", "couac"],
  ["973", "gastronomie", "Le poulet boucané", "Le boucanage donne aux viandes et aux poissons un goût fumé très apprécié en Guyane. Le poulet boucané se retrouve dans les repas populaires et les échoppes. Cette technique raconte une cuisine adaptée au climat, aux fumoirs et aux circulations caribéennes.", 2, "commune", "neutre", "Comité du tourisme de Guyane", "poulet-boucane"],
  ["973", "gastronomie", "Les poissons des fleuves", "En Guyane, les poissons d'eau douce occupent une place importante dans l'alimentation, notamment le long du Maroni et de l'Oyapock. Les recettes varient selon les communautés et les lieux. La gastronomie suit ici les fleuves autant que les marchés urbains.", 2, "commune", "neutre", "Comité du tourisme de Guyane", "poissons-fleuves"],
  ["973", "gastronomie", "Le marché de Cacao", "Le marché de Cacao, village fondé par des familles hmong, est réputé pour ses soupes, fruits, légumes et spécialités asiatiques locales. Il montre la diversité culinaire guyanaise. En Guyane, la gastronomie raconte aussi les migrations récentes et les adaptations tropicales.", 2, "commune", "surprenant", "Comité du tourisme de Guyane", "marche-cacao"],
  ["973", "culture", "Le carnaval de Cayenne", "Le carnaval de Guyane, notamment à Cayenne, mêle bals, parades, touloulous et personnages codifiés. La fête dure plusieurs semaines et possède ses règles propres. En Guyane, le carnaval forme un monde culturel complet, à la fois populaire, masqué et très attendu.", 2, "commune", "amusant", "Comité du tourisme de Guyane", "carnaval-cayenne"],
  ["973", "culture", "Le tembé", "Le tembé est un art graphique associé aux cultures bushinenguées, avec motifs géométriques, couleurs fortes et symboles. On le retrouve sur objets, portes ou fresques. En Guyane, cette expression visuelle donne une place importante aux cultures du fleuve Maroni. Le lieu devient moins abstrait pour le joueur.", 3, "peu commune", "neutre", "Parc amazonien de Guyane", "tembe"],
  ["973", "culture", "Kourou culture spatiale", "À Kourou, le Centre spatial guyanais a créé une culture technique très particulière. Ingénieurs, lancements, visites et écoles vivent au rythme du spatial. En Guyane, les fusées ne sont pas une abstraction lointaine : elles font partie du paysage social.", 2, "commune", "surprenant", "Centre spatial guyanais", "culture-spatiale"],
  ["973", "culture", "Cacao village hmong", "Le village de Cacao est lié à l'installation de familles hmong arrivées en Guyane à partir des années 1970. Marché, artisanat et cultures maraîchères y ont construit une identité forte. En Guyane, la culture territoriale est profondément plurielle. Le detail fait mieux sentir le terrain.", 3, "peu commune", "neutre", "Comité du tourisme de Guyane", "cacao-hmong"],
  ["973", "culture", "Des langues très nombreuses", "La Guyane réunit créoles, langues amérindiennes, langues bushinenguées, français, portugais, hmong et bien d'autres usages. Cette diversité linguistique reflète l'histoire du territoire. En Guyane, la culture se comprend rarement avec une seule langue ou une seule origine. Cette precision donne un repere sensible.", 2, "commune", "pédagogique", "Collectivité territoriale de Guyane", "langues-guyane"],
  ["973", "insolite", "L'Europe en Amazonie", "La Guyane est à la fois un territoire français, européen et amazonien. Cette superposition crée des situations étonnantes : euros, fusées européennes, forêt équatoriale et frontières sud-américaines coexistent. L'insolite tient à ce mélange d'échelles que peu de départements connaissent. Le paysage prend alors une presence nette.", 2, "commune", "surprenant", "Collectivité territoriale de Guyane", "europe-amazonie"],
  ["973", "insolite", "Des fusées dans la forêt", "À Kourou, les lanceurs partent vers l'espace depuis un territoire largement forestier. Le contraste entre haute technologie et Amazonie frappe immédiatement. En Guyane, l'insolite naît de cette proximité entre salle de contrôle, pas de tir, savane littorale et biodiversité tropicale.", 2, "commune", "surprenant", "Centre spatial guyanais", "fusees-foret"],
  ["973", "insolite", "Les tortues luths", "Les plages guyanaises accueillent des pontes de tortues marines, dont la tortue luth, impressionnante par sa taille. Ce spectacle naturel demande protection et discrétion. En Guyane, le littoral mobile devient aussi un lieu majeur pour la faune océanique. Cette mention ajoute une accroche memorable.", 2, "commune", "surprenant", "Office français de la biodiversité Guyane", "tortues-luth"],
  ["973", "insolite", "Des communes sans route", "Certaines communes de Guyane sont accessibles surtout par pirogue ou par avion. Cette réalité change le rapport au temps, aux services et aux distances. En Guyane, l'insolite vient d'un département français où la route n'organise pas tout le territoire. Le point complete la scene sans l'alourdir.", 2, "commune", "surprenant", "Collectivité territoriale de Guyane", "communes-sans-route"],
  ["973", "insolite", "Un pont vers le Brésil", "Le pont sur l'Oyapock relie la Guyane au Brésil, même si les usages frontaliers restent spécifiques. Il matérialise une frontière sud-américaine dans un département français. En Guyane, l'insolite tient parfois à cette évidence géopolitique visible depuis une simple route. L'ensemble devient plus vivant et situe.", 2, "commune", "surprenant", "Préfecture de Guyane", "pont-oyapock"],
];

const countersByDepartmentAndCategory = new Map();

export const anecdotesBatch010 = rawEntries.map(([
  code_departement,
  categorie,
  titre,
  contenu,
  difficulte,
  rarete,
  ton,
  source,
  theme,
]) => {
  const categoryKey = CATEGORY_ID[categorie] ?? categorie;
  const counterKey = `${code_departement}-${categoryKey}`;
  const nextIndex = (countersByDepartmentAndCategory.get(counterKey) ?? 0) + 1;
  countersByDepartmentAndCategory.set(counterKey, nextIndex);

  return {
    id: `${code_departement}-${categoryKey}-${String(nextIndex).padStart(3, "0")}`,
    code_departement,
    titre,
    contenu,
    categorie,
    difficulte,
    rarete,
    ton,
    contexte: CONTEXT,
    source,
    statut_validation: STATUS,
    theme,
    date_ajout: DATE,
    date_modification: DATE,
  };
});
